UPDATE character_profiles SET base_stats_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(base_stats_json) UNION ALL SELECT value FROM json_each('[{"id":"HPMaxBase","label":"ОЗ","value":"1270"},{"id":"AtkBase","label":"АТК","value":"83"},{"id":"DefBase","label":"ЗАЩ","value":"75"},{"id":"CritBase","label":"Шанс крит.","value":"5%"},{"id":"CritDamageBase","label":"Урон крит.","value":"50%"},{"id":"DamageResistPsychically","label":"Сопр. урону когнитивности","value":"0%"},{"id":"DamageResistCosmos","label":"Сопротивление космосу","value":"0%"},{"id":"DamageResistIncantation","label":"Сопротивление чарам","value":"0%"},{"id":"DamageUpPsycheBase","label":"Бонус к урону психики","value":"0%"},{"id":"DamageResistNature","label":"Сопр. урону анимы","value":"0%"},{"id":"DamageUpPsychicallyBase","label":"Бонус к ментальному урону","value":"0%"},{"id":"UnbalIntensity","label":"Интенсивность разрушения","value":"0"},{"id":"DamageResistLakshana","label":"Сопротивление лакшане","value":"0%"},{"id":"DamageUpGeneralBase","label":"Бонус к урону","value":"0%"},{"id":"DamageUpIncantationBase","label":"Бонус к урону чар","value":"0%"},{"id":"ChargeGetEfficiencyBase","label":"Скорость зарядки","value":"100%"},{"id":"DamageUpLakshanaBase","label":"Бонус к урону лакшаны","value":"0%"},{"id":"DamageResistPsyche","label":"Сопротивление психике","value":"0%"},{"id":"Mag","label":"Интенсивность цикла","value":"0"},{"id":"DamageUpChaosBase","label":"Бонус к урону хаоса","value":"0%"},{"id":"DamageUpNatureBase","label":"Бонус к урону анимы","value":"0%"},{"id":"DamageUpCosmosBase","label":"Бонус к урону космоса","value":"0%"},{"id":"DamageResistChaos","label":"Сопротивление хаосу","value":"0%"}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

UPDATE character_profiles SET abilities_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(abilities_json) UNION ALL SELECT value FROM json_each('[{"id":"GA_Elyms_Melee","name":"Мгновенный сбой","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/fea48236d01734f70863.webp","description":"Мгновенный сбой\nТоска по мгновенному ответу.\n\nСвязь Элимс имеет несколько уровней Мощности сигнала. Когда её Мощность сигнала находится на Низком уровне сигнала, она управляет «Терминалом былых грёз», выполняя до пяти последовательных атак и нанося урон космоса.\n\nПосле последнего удара навыка «Мгновенный сбой» Элимс может в течение ограниченного времени напрямую использовать «Прерывистое существование».\n\nПерекрёстные помехи\nСожаление, которое не подвластно времени.\n\nКогда Мощность сигнала находится на Среднем уровне сигнала или Высоком уровне сигнала, Элимс управляет «Терминалом былых грёз», выполняя до трёх последовательных атак и нанося урон космоса.\n\nПосле последнего удара навыка «Перекрёстные помехи» в состоянии «Средний уровень сигнала» или «Высокий уровень сигнала» Элимс может в течение ограниченного времени напрямую использовать «Прощание с тобой».\n\nПомехи\nВсё ещё немного размыто…\n\nУдерживайте кнопку базовой атаки во время «Мгновенного сбоя», когда у Элимс низкий уровень сигнала, чтобы активировать «Помехи» и нанести урон космоса.\n\nЯкорь памяти\nДавай… вспомним это ещё раз…\n\nНажмите кнопку «Целиться» на любом уровне Мощности сигнала, чтобы применить «Якорь памяти» и нанести урон космоса.\n\nСон о падении\nОчередное падение во сне.\n\nНажмите кнопку базовой атаки в воздухе, чтобы выполнить атаку в падении. При приземлении Элимс наносит 1 удар с уроном космоса по области. Урон увеличивается в зависимости от высоты падения; максимальное увеличение составляет 100 %.\n\nЛадно! По рукам!\nДай пять! Чокнемся кулачками! Друзья навек!\n\nСрабатывает при нажатии кнопки базовой атаки Элимс после критического уклонения, нанося урон космоса.\n\nЗаметка о наблюдении № ■■■\n\nТема исследования: Мгновенный обмен сообщениями\n\nМгновенный обмен сообщениями возник из человеческого стремления «получить немедленный ответ». Отправитель может напечатать «то, что у него наболело», и получить ответ от получателя.\n\nПодобные связи нестабильны. Получатель взаимодействует с цифровым аватаром отправителя, но ответит ли этот аватар, зависит исключительно от его человеческого оригинала.\n\nЭксперимент с испытуемым № ■■■ показал, что кратковременная потеря связи между цифровым аватаром и его человеческим оригиналом значительно повышает уровень удовлетворённости с обеих сторон.\n\nИсследование продолжается.","attributes":[{"id":"parameter-0","label":"Множитель урона 1-го удара «Мгновенного сбоя»","value":"1: 11.2 % *2 · 2: 12.1 % *2 · 3: 13.1 % *2 · 4: 14.1 % *2 · 5: 15.2 % *2 · 6: 16.5 % *2 · 7: 17.8 % *2 · 8: 19.2 % *2 · 9: 20.7 % *2 · 10: 22.4 % *2 · 11: 24.2 % *2 · 12: 26.1 % *2 · 13: 28.2 % *2"},{"id":"parameter-1","label":"Множитель урона 2-го удара «Мгновенного сбоя»","value":"1: 15.7 % *2 · 2: 17 % *2 · 3: 18.3 % *2 · 4: 19.8 % *2 · 5: 21.4 % *2 · 6: 23.1 % *2 · 7: 24.9 % *2 · 8: 26.9 % *2 · 9: 29.1 % *2 · 10: 31.4 % *2 · 11: 33.9 % *2 · 12: 36.6 % *2 · 13: 39.5 % *2"},{"id":"parameter-2","label":"Множитель урона 3-го удара «Мгновенного сбоя»","value":"1: 33.4 % *2 + 16.6 % · 2: 36.1 % *2 + 17.9 % · 3: 39 % *2 + 19.4 % · 4: 42.1 % *2 + 20.9 % · 5: 45.4 % *2 + 22.6 % · 6: 49.1 % *2 + 24.4 % · 7: 53 % *2 + 26.3 % · 8: 57.2 % *2 + 28.4 % · 9: 61.8 % *2 + 30.7 % · 10: 66.8 % *2 + 33.2 % · 11: 72.1 % *2 + 35.8 % · 12: 77.9 % *2 + 38.7 % · 13: 84.1 % *2 + 41.8 %"},{"id":"parameter-3","label":"Множитель урона 4-го удара «Мгновенного сбоя»","value":"1: 13.8 % *3 + 14.2 % *2 · 2: 14.9 % *3 + 15.3 % *2 · 3: 16.1 % *3 + 16.6 % *2 · 4: 17.4 % *3 + 17.9 % *2 · 5: 18.8 % *3 + 19.3 % *2 · 6: 20.3 % *3 + 20.9 % *2 · 7: 21.9 % *3 + 22.5 % *2 · 8: 23.7 % *3 + 24.3 % *2 · 9: 25.5 % *3 + 26.3 % *2 · 10: 27.6 % *3 + 28.4 % *2 · 11: 29.8 % *3 + 30.7 % *2 · 12: 32.2 % *3 + 33.1 % *2 · 13: 34.8 % *3 + 35.8 % *2"},{"id":"parameter-4","label":"Множитель урона 5-го удара «Мгновенного сбоя»","value":"1: 91.5 % · 2: 98.8 % · 3: 106.7 % · 4: 115.3 % · 5: 124.5 % · 6: 134.4 % · 7: 145.2 % · 8: 156.8 % · 9: 169.4 % · 10: 182.9 % · 11: 197.5 % · 12: 213.3 % · 13: 230.4 %"},{"id":"parameter-5","label":"Множитель урона «Помех»","value":"1: 10.7 % *2 + 10.7 % + 12.8 % · 2: 11.6 % *2 + 11.6 % + 13.8 % · 3: 12.5 % *2 + 12.5 % + 14.9 % · 4: 13.5 % *2 + 13.5 % + 16.1 % · 5: 14.6 % *2 + 14.6 % + 17.4 % · 6: 15.7 % *2 + 15.7 % + 18.8 % · 7: 17 % *2 + 17 % + 20.3 % · 8: 18.3 % *2 + 18.3 % + 21.9 % · 9: 19.8 % *2 + 19.8 % + 23.7 % · 10: 21.4 % *2 + 21.4 % + 25.6 % · 11: 23.1 % *2 + 23.1 % + 27.6 % · 12: 24.9 % *2 + 24.9 % + 29.8 % · 13: 26.9 % *2 + 26.9 % + 32.2 %"},{"id":"parameter-6","label":"Множитель урона «Якоря памяти»","value":"1: 12 % · 2: 13 % · 3: 14 % · 4: 15.1 % · 5: 16.3 % · 6: 17.6 % · 7: 19 % · 8: 20.6 % · 9: 22.2 % · 10: 24 % · 11: 25.9 % · 12: 28 % · 13: 30.2 %"},{"id":"parameter-7","label":"Множитель урона «Сна о падении»","value":"1: 29.6 % · 2: 32 % · 3: 34.5 % · 4: 37.3 % · 5: 40.3 % · 6: 43.5 % · 7: 47 % · 8: 50.7 % · 9: 54.8 % · 10: 59.2 % · 11: 63.9 % · 12: 69 % · 13: 74.5 %"},{"id":"parameter-8","label":"Множитель урона «Ладно! По рукам!»","value":"1: 100 % · 2: 108 % · 3: 116.6 % · 4: 126 % · 5: 136 % · 6: 146.9 % · 7: 158.7 % · 8: 171.4 % · 9: 185.1 % · 10: 199.9 % · 11: 215.9 % · 12: 233.2 % · 13: 251.8 %"},{"id":"parameter-9","label":"Множитель урона 1-го удара «Перекрёстных помех»","value":"1: 12.4 % + 13.5 % · 2: 13.4 % + 14.6 % · 3: 14.5 % + 15.7 % · 4: 15.6 % + 17 % · 5: 16.9 % + 18.4 % · 6: 18.2 % + 19.8 % · 7: 19.7 % + 21.4 % · 8: 21.3 % + 23.1 % · 9: 23 % + 25 % · 10: 24.8 % + 27 % · 11: 26.8 % + 29.1 % · 12: 28.9 % + 31.5 % · 13: 31.2 % + 34 %"},{"id":"parameter-10","label":"Множитель урона 2-го удара «Перекрёстных помех»","value":"1: 9.3 % *2 + 9.5 % *2 · 2: 10 % *2 + 10.3 % *2 · 3: 10.8 % *2 + 11.1 % *2 · 4: 11.7 % *2 + 12 % *2 · 5: 12.7 % *2 + 12.9 % *2 · 6: 13.7 % *2 + 14 % *2 · 7: 14.8 % *2 + 15.1 % *2 · 8: 15.9 % *2 + 16.3 % *2 · 9: 17.2 % *2 + 17.6 % *2 · 10: 18.6 % *2 + 19 % *2 · 11: 20.1 % *2 + 20.5 % *2 · 12: 21.7 % *2 + 22.2 % *2 · 13: 23.4 % *2 + 23.9 % *2"},{"id":"parameter-11","label":"Множитель урона 3-го удара «Перекрёстных помех»","value":"1: 10.6 % *3 + 47 % · 2: 11.4 % *3 + 50.8 % · 3: 12.4 % *3 + 54.8 % · 4: 13.4 % *3 + 59.2 % · 5: 14.4 % *3 + 63.9 % · 6: 15.6 % *3 + 69.1 % · 7: 16.8 % *3 + 74.6 % · 8: 18.2 % *3 + 80.5 % · 9: 19.6 % *3 + 87 % · 10: 21.2 % *3 + 94 % · 11: 22.9 % *3 + 101.5 % · 12: 24.7 % *3 + 109.6 % · 13: 26.7 % *3 + 118.4 %"},{"id":"parameter-12","label":"Энергия цикла «Мгновенного сбоя»","value":"31"},{"id":"parameter-13","label":"Энергия цикла «Перекрёстных помех»","value":"15"}]},{"id":"GA_Elyms_Skill","name":"Подсчёт электрических овец","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/b663411e5875b92723be.webp","description":"Те, кто ушёл\nКак тот, кому ещё предстоит прийти.\n\nУправляет Терминалом былых грёз, нанося урон космоса целям в области действия.\n\nЕсли Элимс находится в состоянии «Низкий уровень сигнала», после применения этого навыка она может в течение ограниченного времени сразу использовать «Прерывистое существование».\n\nПрерывистое существование\nНепрерывность — это прошлое, неумолимо движущееся вперёд и медленно стирающее будущее.\n\nЭлимс наносит целям в области урон космоса и после применения «Прерывистого существования» в состоянии «Низкий уровень сигнала» повышает Мощность сигнала с Низкого уровня сигнала до Среднего уровня сигнала. Автоматически переключает «У тебя бывает дежавю?» между формами атаки по области и по одной цели в зависимости от количества целей в радиусе действия.\n\nНа ограниченное время даёт усиление «Оптическая иллюзия», когда Мощность сигнала повышается с Низкого уровня сигнала до Среднего уровня сигнала.\n\nПрощание с тобой\nНеизведанный мир — лишь мираж посреди лета, и даже ты — далёкий призрак.\n\nПосле последнего удара «Перекрёстных помех» в состоянии «Средний уровень сигнала» или «Высокий уровень сигнала» Элимс может в течение короткого времени напрямую активировать «Прощание с тобой».\n\nЭлимс наносит целям в области урон космоса. При применении расходует все накопленные заряды Оптической иллюзии, увеличивая множитель урона этого навыка в зависимости от количества израсходованных зарядов.\n\nЕсли Элимс находится в состоянии «Средний уровень сигнала», после применения навыка её Мощность сигнала повышается до Высокого уровня сигнала. Автоматически сканирует ближайшие цели и переключает сверхспособность между формами атаки по области и по одной цели в зависимости от количества обнаруженных целей.\n\nГруппы нет, а музыку… всё равно слышно.\n\nНикакой группы нет и в помине! Это просто… запись.\n\nНет никакой &^%$#@!@#$%^&*&^%$#@!@#$%^&*&^%$#@!@#$%^&*&^%$#, это всё\n\n■■■■■■■■■■■■■■■■■■■■■■■\n\nТишина…\n\nТишина?\n\nТишина.\n\nМой друг.","attributes":[{"id":"parameter-0","label":"Множитель урона «Те, кто ушёл»","value":"1: 26.9 % + 23.6 % *4 + 48.8 % · 2: 29.1 % + 25.5 % *4 + 52.7 % · 3: 31.4 % + 27.5 % *4 + 56.9 % · 4: 33.9 % + 29.7 % *4 + 61.5 % · 5: 36.6 % + 32.1 % *4 + 66.4 % · 6: 39.5 % + 34.7 % *4 + 71.7 % · 7: 42.7 % + 37.5 % *4 + 77.4 % · 8: 46.1 % + 40.4 % *4 + 83.6 % · 9: 49.8 % + 43.7 % *4 + 90.3 % · 10: 53.8 % + 47.2 % *4 + 97.6 % · 11: 58.1 % + 51 % *4 + 105.4 % · 12: 62.7 % + 55 % *4 + 113.8 % · 13: 67.7 % + 59.4 % *4 + 122.9 %"},{"id":"parameter-2","label":"Множитель урона «Прерывистого существования»","value":"1: 10.2 % *5 + 48.8 % · 2: 11 % *5 + 52.7 % · 3: 11.9 % *5 + 56.9 % · 4: 12.8 % *5 + 61.5 % · 5: 13.9 % *5 + 66.4 % · 6: 15 % *5 + 71.7 % · 7: 16.2 % *5 + 77.4 % · 8: 17.5 % *5 + 83.6 % · 9: 18.9 % *5 + 90.3 % · 10: 20.4 % *5 + 97.6 % · 11: 22 % *5 + 105.4 % · 12: 23.8 % *5 + 113.8 % · 13: 25.7 % *5 + 122.9 %"},{"id":"parameter-4","label":"Множитель урона «Прощание с тобой»","value":"1: 13.1 % *5 + 62.2 % · 2: 14.1 % *5 + 67.2 % · 3: 15.3 % *5 + 72.6 % · 4: 16.5 % *5 + 78.4 % · 5: 17.8 % *5 + 84.6 % · 6: 19.2 % *5 + 91.4 % · 7: 20.8 % *5 + 98.7 % · 8: 22.5 % *5 + 106.6 % · 9: 24.2 % *5 + 115.1 % · 10: 26.2 % *5 + 124.3 % · 11: 28.3 % *5 + 134.3 % · 12: 30.5 % *5 + 145 % · 13: 33 % *5 + 156.6 %"},{"id":"parameter-9","label":"Энергия цикла «Те, кто ушёл»","value":"100"}]},{"id":"GA_Elyms_UltraSkill","name":"У тебя бывает дежавю?","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/19788fa0f9e79a2dfa9d.webp","description":"Обычные моменты нашей жизни могут оказаться чудом, что вершится прямо сейчас.\n\nЧей мимолётный силуэт промелькнёт перед тобой в картине из вчерашнего дня?\n\nИмеет форму атаки по одной цели и форму атаки по области.\n\nПри Низком уровне сигнала по умолчанию используется форма атаки по области.\n\nПри Среднем уровне сигнала или Высоком уровне сигнала автоматически переключается между двумя формами в зависимости от результатов сканирования целей навыками «Прерывистое существование», «Прощание с тобой» и «Я здесь», пока Элимс находится на поле боя.\n\nМножитель урона «У тебя бывает дежавю?» зависит от Мощности сигнала на момент применения. После применения или выхода из боя Мощность сигнала сбрасывается до Низкого уровня сигнала.\n\nПосле применения «У тебя бывает дежавю?» даёт всему отряду бонус к атаке на основе базовой атаки Элимс и на ограниченное время увеличивает урон последующих атак отряда.\n\nДаёт усиление «На связи». Пока оно действует, «Воспоминание» автоматически срабатывает как скоординированная атака, если Элимс находится вне поля боя.\n\n«Воспоминание» принимает ту же форму атаки по одной цели или по области, что и предшествующее «У тебя бывает дежавю?», а его множитель урона зависит от Мощности сигнала Элимс на момент применения того навыка.\n\nУрон от «Воспоминания» считается уроном последующей атаки.\n\nУсиление «На связи» заканчивается, когда «Воспоминание» достигает лимита использований.\n\nСамый обычный день. Мы запустили игру, которую всё ещё не прошли, провели время вместе, смеялись над всякими глупостями, заглянули в наше привычное местечко, попрощались и пообещали встретиться снова.\n\nВсё та же рутина — точь-в-точь как вчера.\n\nНичего не изменилось и никогда не изменится. Вот бы всё так и оставалось…\n\nДля подтверждения нажмите 1. Для подтверждения нажмите 2. Для подтверждения нажмите 3. Для подтверждения нажмите 4. Для подтверждения нажмите 5. Для подтверждения нажмите 6. Для подтверждения нажмите 7. Для подтверждения нажмите 8. Для подтверждения нажмите 9. Для подтверждения нажмите 0. Для подтверждения нажмите #.","attributes":[{"id":"parameter-0","label":"Базовый множитель урона «У тебя бывает дежавю?» по области","value":"1: 32 % *3 + 309 % · 2: 34.6 % *3 + 333.7 % · 3: 37.3 % *3 + 360.4 % · 4: 40.3 % *3 + 389.3 % · 5: 43.5 % *3 + 420.4 % · 6: 47 % *3 + 454 % · 7: 50.8 % *3 + 490.3 % · 8: 54.8 % *3 + 529.6 % · 9: 59.2 % *3 + 571.9 % · 10: 64 % *3 + 617.7 % · 11: 69.1 % *3 + 667.1 % · 12: 74.6 % *3 + 720.5 % · 13: 80.6 % *3 + 778.1 %"},{"id":"parameter-3","label":"Базовый множитель урона «У тебя бывает дежавю?» по одной цели","value":"1: 35.6 % *3 + 69.8 % *4 + 64 % · 2: 38.4 % *3 + 75.4 % *4 + 69.1 % · 3: 41.5 % *3 + 81.4 % *4 + 74.6 % · 4: 44.8 % *3 + 87.9 % *4 + 80.6 % · 5: 48.4 % *3 + 95 % *4 + 87.1 % · 6: 52.3 % *3 + 102.6 % *4 + 94 % · 7: 56.5 % *3 + 110.8 % *4 + 101.6 % · 8: 61 % *3 + 119.6 % *4 + 109.7 % · 9: 65.9 % *3 + 129.2 % *4 + 118.5 % · 10: 71.2 % *3 + 139.5 % *4 + 127.9 % · 11: 76.9 % *3 + 150.7 % *4 + 138.2 % · 12: 83 % *3 + 162.7 % *4 + 149.2 % · 13: 89.6 % *3 + 175.8 % *4 + 161.2 %"},{"id":"parameter-11","label":"Базовый множитель урона «Воспоминания» по области","value":"1: 27 % *4 · 2: 29.2 % *4 · 3: 31.5 % *4 · 4: 34 % *4 · 5: 36.7 % *4 · 6: 39.7 % *4 · 7: 42.8 % *4 · 8: 46.3 % *4 · 9: 50 % *4 · 10: 54 % *4 · 11: 58.3 % *4 · 12: 63 % *4 · 13: 68 % *4"},{"id":"parameter-16","label":"Базовый множитель урона «Воспоминания» по одной цели","value":"1: 30 % *4 · 2: 32.4 % *4 · 3: 35 % *4 · 4: 37.8 % *4 · 5: 40.8 % *4 · 6: 44.1 % *4 · 7: 47.6 % *4 · 8: 51.4 % *4 · 9: 55.5 % *4 · 10: 60 % *4 · 11: 64.8 % *4 · 12: 69.9 % *4 · 13: 75.5 % *4"}]},{"id":"GA_Elyms_QTE","name":"Я здесь","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/5caf31608d5c1f4b3dac.webp","description":"В сети! Элимс управляет «Терминалом былых грёз» и наносит урон космоса.\n\nПосле применения «Я здесь», пока Элимс находится на поле боя, повышает состояние «Низкий уровень сигнала» до состояния «Средний уровень сигнала». Элимс проверяет количество целей в определённом радиусе и автоматически переключает «У тебя бывает дежавю?» между формой атаки по одной цели и формой атаки по области.\n\nПри улучшении Низкого уровня сигнала до Среднего уровня сигнала на ограниченное время даёт усиление «Оптическая иллюзия».\n\n«Ты меня помнишь? Я всё это время была здесь».","attributes":[{"id":"parameter-0","label":"Множитель урона «Я здесь»","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Elyms_Passive1","name":"Ретрансляционный узел","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/b5f378a0bb2e8004e343.webp","description":"Усиление Зарядки: каждый раз, когда активный персонаж получает энергию сверхспособности, урон космоса всей команды увеличивается на 3,75 % в течение 30 сек. Эффект складывается до 8 раз. При повторном срабатывании длительность обновляется.\n\nУсиление Реморы: позволяет Элимс повторно накладывать Ремору на ту же цель через 7,5 сек. всякий раз, когда союзник накладывает Ремору. Срабатывает не чаще одного раза в 7 сек. Ремора, наложенная таким способом, не может активировать данный эффект повторно.\n\n«Сигнал слишком слабый! Сейчас я прибавлю мощности!»","attributes":[]},{"id":"GA_Elyms_Passive2","name":"Система гарантии","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/5f9359b3d5309bc6026c.webp","description":"Увеличивает её крит. урон на 10 %.\n\nСамо собой, перед большой битвой мы должны быть в идеальной форме!","attributes":[]},{"id":"GA_Elyms_Passive3","name":"Ты тут?","type":"Черта персонажа","iconUrl":"/nte-meta/game-assets/4417d7950d047790afef.webp","description":"Когда Элимс бездействует, у неё есть шанс активировать свой пассивный навык «Ты тут?». В этом случае она поприветствует вас и вручит небольшой приготовленный подарок. Только один в день!\n\nКуда это тебя занесло?","attributes":[]},{"id":"City_Ability_Elyms_01","name":"Социальная сеть","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/53c17bf8429c23619381.webp","description":"Увеличивает оценку удовлетворённости по заказам, доставленным водителями, на 5 пунктов, пока Элимс назначена помощником по логистике в Логистическом центре.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Увеличивает оценку удовлетворённости по заказам, доставленным водителями, на 5 пунктов, пока Элимс назначена помощником по логистике в Логистическом центре."},{"id":"city-1","label":"Уровень 2","value":"Увеличивает максимальное число водителей-партнёров на 1, пока Элимс назначена помощником по логистике в Логистическом центре."},{"id":"city-2","label":"Уровень 3","value":"Увеличивает оценку удовлетворённости по заказам, доставленным водителями, на 5 пунктов, пока Элимс назначена помощником по логистике в Логистическом центре."},{"id":"city-3","label":"Уровень 4","value":"Увеличивает максимальное число водителей-партнёров на 1, пока Элимс назначена помощником по логистике в Логистическом центре."},{"id":"city-4","label":"Уровень 5","value":"Увеличивает на 1 количество водителей, которых можно отправить одновременно, если Элимс назначена помощницей по логистике в логистическом центре."}]},{"id":"City_Ability_Elyms_02","name":"Социальные связи","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/dd3979891f0f893b9685.webp","description":"«Раз, два, продано!»: уменьшает количество коллекционных предметов, необходимых для 1-го обмена на мебель в витрине коллекции, на 1. (Сбрасывается с каждым циклом обмена.)","attributes":[{"id":"city-0","label":"Уровень 1","value":"«Раз, два, продано!»: уменьшает количество коллекционных предметов, необходимых для 1-го обмена на мебель в витрине коллекции, на 1. (Сбрасывается с каждым циклом обмена.)"},{"id":"city-1","label":"Уровень 2","value":"Изменение эффекта в «Раз, два, продано!»: уменьшает количество коллекционных предметов, необходимых для каждого из первых 2 обменов на мебель в витрине коллекции, на 1. (Сбрасывается с каждым циклом обмена.)"}]}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

UPDATE character_profiles SET skins_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(skins_json) UNION ALL SELECT value FROM json_each('[{"id":"Fashion_1090_nighty","name":"Ветроцвет","imageUrl":"/nte-meta/game-assets/405cde4e76901c7c4189.webp","description":"Награда за 10-й уровень связи с Элимс."},{"id":"Fashion_1090_0","name":"Лейтенант во плоти","imageUrl":"/nte-meta/game-assets/5c7f06ecc2d2f411dd7d.webp","description":""},{"id":"Fashion_1090_1","name":"Мистика Y2K","imageUrl":"/nte-meta/game-assets/d14ce0f922d9abd0f12a.webp","description":"Постоянный облик в магазине; стартовая скидка действует до 23 декабря 2026, 05:59 (UTC+8)."},{"id":"Fashion_1090_2","name":"Парящие лепестки","imageUrl":"/nte-meta/game-assets/1330b3cb684ecd4023fc.webp","description":"Награда доски «Мечты андроида»: соответствующая клетка или 200 бросков для получения через бонусы."}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

