{"id":"reward-10-1","name":"Офицер связи","quantity":"1","iconUrl":"/nte-meta/game-assets/b7dcf14a099d6e8a4085.webp"},{"id":"reward-10-2","name":"Ветроцвет","quantity":"1","iconUrl":"/nte-meta/game-assets/02f1c9b516dce4162581.webp"}]}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

UPDATE character_profiles SET gifts_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(gifts_json) UNION ALL SELECT value FROM json_each('[{"id":"Food_096","name":"Гляделки! Кто первый моргнёт!","iconUrl":"/nte-meta/game-assets/07ff8fcc692084fd3aeb.webp","effect":"Симпатия +100"},{"id":"Food_097","name":"Великий защитник!","iconUrl":"/nte-meta/game-assets/493a4e445d1e1b4da36c.webp","effect":"Симпатия +100"},{"id":"Food_143","name":"Тоник грёз","iconUrl":"/nte-meta/game-assets/bf049aa657e58f041f7c.webp","effect":"Симпатия +100"},{"id":"Flower0024","name":"Стихающий дождь","iconUrl":"/nte-meta/game-assets/92866ee21a58f6e26ee6.webp","effect":"Симпатия +200"},{"id":"SpecialGift_elyms1","name":"Наклейка «Лучшие друзья»","iconUrl":"/nte-meta/game-assets/39aa47f45b1891e06cf5.webp","effect":"Симпатия +200"},{"id":"SpecialGift_elyms2","name":"Значок «Маленький призрак»","iconUrl":"/nte-meta/game-assets/e82e013561a572b05410.webp","effect":"Симпатия +200"},{"id":"SpecialGift_elyms3","name":"Меланхоличный бумажный самолётик","iconUrl":"/nte-meta/game-assets/252bc44bb339f9460a76.webp","effect":"Симпатия +200"},{"id":"Furniture_Light_003","name":"Ретро-абажур","iconUrl":"/nte-meta/game-assets/7457f2bb8ccc86d5fe17.webp","effect":"Симпатия +400"},{"id":"Furniture_Ornament_031","name":"Камера","iconUrl":"/nte-meta/game-assets/bf24f69fd3ecdd212d1e.webp","effect":"Симпатия +400"},{"id":"Furniture_Ornament_038","name":"999 ночей","iconUrl":"/nte-meta/game-assets/dd5fff5ecab7f5a5d860.webp","effect":"Симпатия +400"},{"id":"Furniture_draw_008","name":"Одиночество","iconUrl":"/nte-meta/game-assets/ec518e4c2623d929f849.webp","effect":"Симпатия +400"},{"id":"SpecialGift_ticket","name":"Билет в кинотеатр «Флоу»","iconUrl":"/nte-meta/game-assets/99060c23d3e0fef0599d.webp","effect":"Симпатия +400"},{"id":"SpecialGift_1090","name":"Ностальгический чехол для телефона","iconUrl":"/nte-meta/game-assets/a984b1de032b3da984b9.webp","effect":"Симпатия +1200"},{"id":"SpecialGift_letter","name":"Рукописное письмо","iconUrl":"/nte-meta/game-assets/3deebe64fe65e4e200c3.webp","effect":"Симпатия +2000"}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"ja-Play_Vo_Char_NPC030_about_005","title":"О ТОИ-6","language":"Японский","audioUrl":"/nte-meta/game-audio/d4904faa5b1278188af1.ogg","sourceUrl":"","description":"Бюро считает отряд из четырёх человек идеальным составом для подразделений ТОИ. Как только команда достигает этого числа, они больше никого не берут. Хм-м, думаешь, у нас и так тесновато? А Ница на очереди в резерв?.. Это всё потому, что квота не распространяется на напарников-аномалий. Вот Сяочжэнь, например, тоже не считается. Так что в нашем отряде всё ещё свободно одно место."},{"id":"ja-Play_Vo_Char_NPC030_hstruck_002","title":"Сильный урон II","language":"Японский","audioUrl":"/nte-meta/game-audio/59fbc00b8a0351465d50.ogg","sourceUrl":"","description":"Сильные помехи."},{"id":"zh-Play_Vo_Char_NPC030_about_001","title":"Об ЭКЗЕ","language":"Китайский","audioUrl":"/nte-meta/game-audio/6d6d932d94561cfbc08e.ogg","sourceUrl":"","description":"Дай-ка подумать… «1. С Экзе работа распределяется эффективно, что приносит выдающиеся результаты; 2. Наше ежедневное общение искренне и прямолинейно, обе стороны без стеснения высказывают всё, что считают нужным; 3. У каждой из сторон сформировалось глубокое понимание рабочего стиля, привычек и больных тем друг друга; Дополнительное примечание: обе стороны подтверждают, что на сегодняшний день никаких внутренних конфликтов по рабочим вопросам не возникало, и в будущем их не предвидится». …Хм-м, отлично, на этом и остановлюсь. Чистая правда, никакой лжи."},{"id":"zh-Play_Vo_Char_NPC030_deploy_001","title":"Отправка I","language":"Китайский","audioUrl":"/nte-meta/game-audio/c4393e45a83fc67a514e.ogg","sourceUrl":"","description":"Позвони мне — и я сразу буду рядом!"},{"id":"zh-Play_Vo_Char_NPC030_skill_005","title":"Навык перенаправления V","language":"Китайский","audioUrl":"/nte-meta/game-audio/80c5ecae1449222ec7df.ogg","sourceUrl":"","description":"Пиу-пиу!"},{"id":"ko-Play_Vo_Char_NPC030_chat_002","title":"Чат: Начать разговор","language":"Корейский","audioUrl":"/nte-meta/game-audio/96ab1c3a30ca3108f4c2.ogg","sourceUrl":"","description":"Как по мне, если уж начинать разговор, то надёжнее всего сразу переходить к делу и говорить всё как есть. Вот взять меня, к примеру — ха, я тут просто чтобы узнать, как ты! Случилось чего в последнее время, чем хочется поделиться с подругой? Хоть хорошее, хоть плохое — мне всё интересно!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_FDY_001","title":"Особое переключение — Фадия","language":"Корейский","audioUrl":"/nte-meta/game-audio/ab0575e4dd3089220284.ogg","sourceUrl":"","description":"Фадия, на тебя опять пожаловались?"},{"id":"ko-Play_Vo_Char_NPC030_SSC_ZERO_002","title":"Особое переключение II — Ноль","language":"Корейский","audioUrl":"/nte-meta/game-audio/51e5661f2832bce18c3d.ogg","sourceUrl":"","description":"Ладно, теперь моя очередь тебе помочь!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_FDY_001","title":"Особое переключение — Фадия","language":"Китайский","audioUrl":"/nte-meta/game-audio/ec8994a7ff1606776d9d.ogg","sourceUrl":"","description":"Фадия, на тебя опять пожаловались?"},{"id":"en-Play_Vo_Char_NPC030_about_002","title":"О Хаосе","language":"Английский","audioUrl":"/nte-meta/game-audio/af73f0d158dcb0c0efd8.ogg","sourceUrl":"","description":"Выбрать рингтон для Хаоса — та ещё головная боль. Чтобы связь добивала до передовой, мне нужно, чтобы он хватал трубку в ту же секунду, как услышит звонок. Если мелодия будет слишком мягкой, он её просто не заметит, когда увлечётся дракой или пойдёт по горячему следу цели. А если будет слишком громкой, он начнёт мне жаловаться… О! Придумала! Музыка, которая играет на экране победы в «Тетрамино»! Она ведь такая бодрая, да?"},{"id":"ja-Play_Vo_Char_NPC030_kill_002","title":"Убийство II","language":"Японский","audioUrl":"/nte-meta/game-audio/bff2458b41cb2136221d.ogg","sourceUrl":"","description":"Ты ещё вернёшься!"},{"id":"ja-Play_Vo_Char_NPC030_meet_001","title":"Первая встреча","language":"Японский","audioUrl":"/nte-meta/game-audio/2e003a6f96936a2258f3.ogg","sourceUrl":"","description":"Привет-привет, это же я! Давненько не виделись, а? Как поживаешь?.. Я? Ну, на данный момент я лейтенант 6-го отряда ТОИ в ББА. Ха-ха, вот уж нежданчик, правда? Моё имя?.. Эй, только не говори, что не помнишь, как меня зовут!"},{"id":"ko-Play_Vo_Char_NPC030_greet_003","title":"Вечернее приветствие","language":"Корейский","audioUrl":"/nte-meta/game-audio/2eea9c251b72df39eb54.ogg","sourceUrl":"","description":"Заходящее солнце… из-за него всегда кажется, будто пришло время прощаться с другом. От всей этой атмосферы становится так радостно и грустно одновременно."},{"id":"ko-Play_Vo_Char_NPC030_struck_002","title":"Урон II","language":"Корейский","audioUrl":"/nte-meta/game-audio/560a9289085bd8c1d24d.ogg","sourceUrl":"","description":"Небольшое возмущение…"},{"id":"zh-Play_Vo_Char_NPC030_aoe_UI_002","title":"Сверхспособность II","language":"Китайский","audioUrl":"/nte-meta/game-audio/1ea16956ed0f7435a285.ogg","sourceUrl":"","description":"Пора играть! Погнали!"},{"id":"zh-Play_Vo_Char_NPC030_containment_001","title":"Сдерживание I","language":"Китайский","audioUrl":"/nte-meta/game-audio/a17746f84156fd59609f.ogg","sourceUrl":"","description":"Тебе одиноко? Продержись ещё немножко."},{"id":"en-Play_Vo_Char_NPC030_dead_001","title":"Потеря сознания I","language":"Английский","audioUrl":"/nte-meta/game-audio/c3cc78e9577dfc767428.ogg","sourceUrl":"","description":"Связь обрывается…"},{"id":"en-Play_Vo_Char_NPC030_SSC_KES_002","title":"Особое переключение II — Хаос","language":"Английский","audioUrl":"/nte-meta/game-audio/fe0e8a8ed40252c572bc.ogg","sourceUrl":"","description":"Всю грязную работёнку оставляю тебе, бро!"},{"id":"en-Play_Vo_Char_NPC030_windfall_001","title":"Неожиданная добыча I","language":"Английский","audioUrl":"/nte-meta/game-audio/b71649fdfb8f65c54dd5.ogg","sourceUrl":"","description":"Может, позвонить кому-нибудь и узнать, кто это потерял?"},{"id":"ja-Play_Vo_Char_NPC030_about_001","title":"Об ЭКЗЕ","language":"Японский","audioUrl":"/nte-meta/game-audio/c7203a2d538d8899f4b3.ogg","sourceUrl":"","description":"Дай-ка подумать… «1. С Экзе работа распределяется эффективно, что приносит выдающиеся результаты; 2. Наше ежедневное общение искренне и прямолинейно, обе стороны без стеснения высказывают всё, что считают нужным; 3. У каждой из сторон сформировалось глубокое понимание рабочего стиля, привычек и больных тем друг друга; Дополнительное примечание: обе стороны подтверждают, что на сегодняшний день никаких внутренних конфликтов по рабочим вопросам не возникало, и в будущем их не предвидится». …Хм-м, отлично, на этом и остановлюсь. Чистая правда, никакой лжи."},{"id":"ja-Play_Vo_Char_NPC030_containment_001","title":"Сдерживание I","language":"Японский","audioUrl":"/nte-meta/game-audio/24edd53a58fd24ebbfad.ogg","sourceUrl":"","description":"Тебе одиноко? Продержись ещё немножко."},{"id":"ja-Play_Vo_Char_NPC030_QTE_003","title":"Атака на входе III","language":"Японский","audioUrl":"/nte-meta/game-audio/a8e9ca3f7c7e132aad0c.ogg","sourceUrl":"","description":"Привет!"},{"id":"ja-Play_Vo_Char_NPC030_windfall_003","title":"Неожиданная добыча III","language":"Японский","audioUrl":"/nte-meta/game-audio/24dee7d4a08571ae2367.ogg","sourceUrl":"","description":"Тебе это пригодится. Держи!"},{"id":"ko-Play_Vo_Char_NPC030_gift_001","title":"Подарок получен I","language":"Корейский","audioUrl":"/nte-meta/game-audio/c7f73573b7646082a542.ogg","sourceUrl":"","description":"Какой классный подарок! Надо бы найти ему местечко…"},{"id":"zh-Play_Vo_Char_NPC030_chat_001","title":"Чат: Ты тут?","language":"Китайский","audioUrl":"/nte-meta/game-audio/8d3817d3b9fc3a5a49a1.ogg","sourceUrl":"","description":"Многих прямо трясёт, когда им пишут «ты тут?», прежде чем вообще объяснить, чего хотят. И если честно, твой ответ на вопрос «Ты тут?» во многом зависит от того, что именно собираются сказать дальше. Если это что-то, чего хочется избежать, в глубине души хочется просто исчезнуть из сети. Забавно всё-таки устроена человеческая психология, да?"},{"id":"zh-Play_Vo_Char_NPC030_weather_001","title":"Солнечно","language":"Китайский","audioUrl":"/nte-meta/game-audio/cd27d9760dfbf4df8214.ogg","sourceUrl":"","description":"В такую отличную погоду просто грех сидеть дома — надо выбраться куда-нибудь и забить день планами до отказа, верно?"},{"id":"zh-Play_Vo_Char_NPC030_windfall_001","title":"Неожиданная добыча I","language":"Китайский","audioUrl":"/nte-meta/game-audio/6b1e35495c027173ef89.ogg","sourceUrl":"","description":"Может, позвонить кому-нибудь и узнать, кто это потерял?"},{"id":"en-Play_Vo_Char_NPC030_SSC_YI_001","title":"Особое переключение — Ския","language":"Английский","audioUrl":"/nte-meta/game-audio/6966049ab7ce8e6e0c93.ogg","sourceUrl":"","description":"Ския, не переживай, я возьму это на себя."},{"id":"ko-Play_Vo_Char_NPC030_aoe_UI_001","title":"Сверхспособность I","language":"Корейский","audioUrl":"/nte-meta/game-audio/a6e91976314353aab775.ogg","sourceUrl":"","description":"Давай сегодня сыграем ещё раз!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_AHQ_001","title":"Особое переключение — Лакримоза","language":"Корейский","audioUrl":"/nte-meta/game-audio/ce24df3f19825c8da949.ogg","sourceUrl":"","description":"Мозочка, можешь ещё немного поспать."},{"id":"ko-Play_Vo_Char_NPC030_talk_003","title":"Тема: Контакт","language":"Корейский","audioUrl":"/nte-meta/game-audio/bef2bbd1c4de0ae6389e.ogg","sourceUrl":"","description":"Любая связь рано или поздно обрывается. День за днём люди принимают эти узы как должное, совершенно забывая о том, что им может прийти конец. Представь, что каждые отношения — это кабель передачи данных, обёрнутый вокруг твоего пальца. Если бы люди могли своими глазами видеть, как он провисает, сворачивается кольцами, пружинит, натягивается струной, истирается, пускает трещины и в конце концов рвётся… неужели они не стали бы охотнее писать то самое лишнее сообщение, делать тот самый лишний звонок и изливать душу тем, кто им по-настоящему дорог?"},{"id":"ko-Play_Vo_Char_NPC030_ug_003","title":"Вознесение персонажа III","language":"Корейский","audioUrl":"/nte-meta/game-audio/39ca02f9f514b4852540.ogg","sourceUrl":"","description":"Такое чувство, будто я могу дозвониться в мгновение ока, даже туда, где вообще не ловит сеть."},{"id":"zh-Play_Vo_Char_NPC030_hp_003","title":"Низкий уровень здоровья III","language":"Китайский","audioUrl":"/nte-meta/game-audio/7469ed1df4e082bc0933.ogg","sourceUrl":"","description":"Флуктуации усиливаются…"},{"id":"en-Play_Vo_Char_NPC030_Parry_001","title":"Парирование I","language":"Английский","audioUrl":"/nte-meta/game-audio/a3c8234ad35ded21cae5.ogg","sourceUrl":"","description":"Конечно, давай пожмём руки!"},{"id":"ko-Play_Vo_Char_NPC030_gift_003","title":"Подарок получен III","language":"Корейский","audioUrl":"/nte-meta/game-audio/e89501eb809dbe5155df.ogg","sourceUrl":"","description":"Ого, это что, маленький дружеский сюрприз?"},{"id":"zh-Play_Vo_Char_NPC030_Fly_002","title":"Планирование II","language":"Китайский","audioUrl":"/nte-meta/game-audio/48b52902aaf6e1c95c1b.ogg","sourceUrl":"","description":"Сливаюсь с воздухом!"},{"id":"zh-Play_Vo_Char_NPC030_Switch_001","title":"Переключение I","language":"Китайский","audioUrl":"/nte-meta/game-audio/01886326510d9222a3db.ogg","sourceUrl":"","description":"Моя проекция уже здесь!"},{"id":"zh-Play_Vo_Char_NPC030_TeammateDown_002","title":"Поражён товарищ по команде — Хаос","language":"Китайский","audioUrl":"/nte-meta/game-audio/b1326a9cb3f58b399dc9.ogg","sourceUrl":"","description":"Не время для последних слов. Это ещё не конец!"},{"id":"ko-Play_Vo_Char_NPC030_hp_003","title":"Низкий уровень здоровья III","language":"Корейский","audioUrl":"/nte-meta/game-audio/bde33debeae6eab824ed.ogg","sourceUrl":"","description":"Флуктуации усиливаются…"},{"id":"ko-Play_Vo_Char_NPC030_self_003","title":"Обо мне: Существование","language":"Корейский","audioUrl":"/nte-meta/game-audio/5a0284fa945c0994b714.ogg","sourceUrl":"","description":"Существую ли я? Ты видишь модель персонажа, интерфейсы, текст, слышишь эту звуковую дорожку и прекрасно понимаешь, что всё это — лишь единицы и нули. Иллюзия, сотканная из цифр и сигналов. Так что, полагаю, для тебя в тот самый миг, когда всё это потеряет смысл, я с тем же успехом могла бы вообще никогда не существовать! А что до смысла, то он должен исходить из «причины» твоего бытия — из вопроса «почему» или «why» — буквы Y. Самое забавное, что с того самого мгновения, как я появилась на свет, у меня уже была моя «Y». И вот ответ на твой вопрос: «Да. Для себя я существую»."},{"id":"ko-Play_Vo_Char_NPC030_SSC_LK_002","title":"Особое переключение II — Линко","language":"Корейский","audioUrl":"/nte-meta/game-audio/554b44abe2966eec12df.ogg","sourceUrl":"","description":"Давай я найду тебе какое-нибудь классное занятие!"},{"id":"zh-Play_Vo_Char_NPC030_self_003","title":"Обо мне: Существование","language":"Китайский","audioUrl":"/nte-meta/game-audio/c5a3ae1a5f7ab7632878.ogg","sourceUrl":"","description":"Существую ли я? Ты видишь модель персонажа, интерфейсы, текст, слышишь эту звуковую дорожку и прекрасно понимаешь, что всё это — лишь единицы и нули. Иллюзия, сотканная из цифр и сигналов. Так что, полагаю, для тебя в тот самый миг, когда всё это потеряет смысл, я с тем же успехом могла бы вообще никогда не существовать! А что до смысла, то он должен исходить из «причины» твоего бытия — из вопроса «почему» или «why» — буквы Y. Самое забавное, что с того самого мгновения, как я появилась на свет, у меня уже была моя «Y». И вот ответ на твой вопрос: «Да. Для себя я существую»."},{"id":"en-Play_Vo_Char_NPC030_chat_002","title":"Чат: Начать разговор","language":"Английский","audioUrl":"/nte-meta/game-audio/dfa25f34631b8da92836.ogg","sourceUrl":"","description":"Как по мне, если уж начинать разговор, то надёжнее всего сразу переходить к делу и говорить всё как есть. Вот взять меня, к примеру — ха, я тут просто чтобы узнать, как ты! Случилось чего в последнее время, чем хочется поделиться с подругой? Хоть хорошее, хоть плохое — мне всё интересно!"},{"id":"en-Play_Vo_Char_NPC030_QTE_002","title":"Атака на входе II","language":"Английский","audioUrl":"/nte-meta/game-audio/7d4225a87ef444d95184.ogg","sourceUrl":"","description":"Время пришло!"},{"id":"en-Play_Vo_Char_NPC030_self_002","title":"Обо мне: Общение","language":"Английский","audioUrl":"/nte-meta/game-audio/07d3c41e62c0999a104c.ogg","sourceUrl":"","description":"Закрытую связь нашего отряда настраивает не Чуппа, это моя собственная специальная сборка. В основу системы я заложила «людей и их социальные связи». Плюс в том, что она может передавать не только голос, но и генерировать объекты прямо на месте — включая моих аватаров или инструменты, которые экспортирует Экзе. Минус — она почти не работает в безлюдных зонах далеко за городом или внутри аномальных измерений, отрезанных от сети. О, но если тебе кровь из носу нужно будет связаться со мной в каком-нибудь подобном месте, есть способ хлопотнее: тебе придётся ненадолго погрузиться в собственное подсознание…"},{"id":"ja-Play_Vo_Char_NPC030_aoe_UI_002","title":"Сверхспособность II","language":"Японский","audioUrl":"/nte-meta/game-audio/7cf7be7b3641234da80c.ogg","sourceUrl":"","description":"Пора играть! Погнали!"},{"id":"ja-Play_Vo_Char_NPC030_ug_002","title":"Вознесение персонажа II","language":"Японский","audioUrl":"/nte-meta/game-audio/20848b2082dc5569b8a8.ogg","sourceUrl":"","description":"Моя проекция стала чуть чётче?"},{"id":"zh-Play_Vo_Char_NPC030_kill_002","title":"Убийство II","language":"Китайский","audioUrl":"/nte-meta/game-audio/5ea88dec697da1e74723.ogg","sourceUrl":"","description":"Ты ещё вернёшься!"},{"id":"zh-Play_Vo_Char_NPC030_self_001","title":"Обо мне: работа","language":"Китайский","audioUrl":"/nte-meta/game-audio/baf7d5c20e0b82bbf77c.ogg","sourceUrl":"","description":"Что касается Экзе, я проверяю его отчёты и переписываю всё, что совершенно не похоже на живую человеческую речь. Иногда я даже захожу под его аккаунтом, чтобы говорить от его имени или сглаживать углы в отношениях с другими отделами, которые он умудряется портить в одиночку и абсолютно непреднамеренно. Для Хаоса я синхронизирую разведданные прямо во время операций. А ещё я всегда наготове, чтобы проанализировать ключевые слова в его сообщениях, когда он упоминает какую-нибудь современную вещь, которую явно не знает, как назвать. С Линко я постоянно остаюсь на связи, чтобы подстраховать её в ту же секунду, как она окажется в изоляции. Я звоню ей без предупреждения, чтобы следить, вовремя ли она ложится, рано ли встаёт, идёт ли домой и не засиживается ли с ночи до утра. А ещё я созваниваюсь с её родителями, рассказываю о её успехах и вместе с ними нахваливаю их дочь…"},{"id":"en-Play_Vo_Char_NPC030_chat_003","title":"Чат: Продолжить общение","language":"Английский","audioUrl":"/nte-meta/game-audio/1cda44a3a5b9e5e72a6a.ogg","sourceUrl":"","description":"Некоторые люди так боятся неловкого молчания, что вообще не решаются заговорить. Звучит немного парадоксально, но понять их можно. В таких случаях приходится считывать атмосферу, чтобы сообразить, куда повернуть беседу. Безопаснее всего переключиться на что-то банальное вроде погоды или свежих новостей. Хотя и это может выйти боком… Иногда просто не везёт…"},{"id":"en-Play_Vo_Char_NPC030_meet_001","title":"Первая встреча","language":"Английский","audioUrl":"/nte-meta/game-audio/69ddd3ffc068a08fce4f.ogg","sourceUrl":"","description":"Привет-привет, это же я! Давненько не виделись, а? Как поживаешь?.. Я? Ну, на данный момент я лейтенант 6-го отряда ТОИ в ББА. Ха-ха, вот уж нежданчик, правда? Моё имя?.. Эй, только не говори, что не помнишь, как меня зовут!"},{"id":"en-Play_Vo_Char_NPC030_Parry_002","title":"Парирование II","language":"Английский","audioUrl":"/nte-meta/game-audio/b288ae5caa94a6c1e7bd.ogg","sourceUrl":"","description":"Достойный ответ."},{"id":"en-Play_Vo_Char_NPC030_talk_001","title":"Тема: Имя контакта","language":"Английский","audioUrl":"/nte-meta/game-audio/97b3f52e1aa2f5e51d1b.ogg","sourceUrl":"","description":"Имена менять проще простого. Если попросишь, я тебе мигом новое придумаю. Я ж говорю: это примерно то же самое, что поставить ник контакту в соцсетях. К тому же никнейм порой значит куда больше, чем настоящее имя. Хочешь, я дам тебе какое-нибудь особенное прозвище? Как тебе, например, «Какао» или «Прелесть»?"},{"id":"ja-Play_Vo_Char_NPC030_SSC_FDY_001","title":"Особое переключение — Фадия","language":"Японский","audioUrl":"/nte-meta/game-audio/e0c02559869664d1289c.ogg","sourceUrl":"","description":"Фадия, на тебя опять пожаловались?"},{"id":"ja-Play_Vo_Char_NPC030_Switch_003","title":"Переключение III","language":"Японский","audioUrl":"/nte-meta/game-audio/56f72245b8e37395e5cc.ogg","sourceUrl":"","description":"С проекцией всё стабильно?"},{"id":"ja-Play_Vo_Char_NPC030_windfall_002","title":"Неожиданная добыча II","language":"Японский","audioUrl":"/nte-meta/game-audio/2e9d83bcdb21f33f0213.ogg","sourceUrl":"","description":"Предмет найден, докладываю!"},{"id":"ko-Play_Vo_Char_NPC030_ug_001","title":"Вознесение персонажа I","language":"Корейский","audioUrl":"/nte-meta/game-audio/c4c73f837542c90ef970.ogg","sourceUrl":"","description":"Связь стала стабильнее!"},{"id":"en-Play_Vo_Char_NPC030_weather_001","title":"Солнечно","language":"Английский","audioUrl":"/nte-meta/game-audio/3bb3ae8323bb1aed9a14.ogg","sourceUrl":"","description":"В такую отличную погоду просто грех сидеть дома — надо выбраться куда-нибудь и забить день планами до отказа, верно?"},{"id":"ja-Play_Vo_Char_NPC030_chat_001","title":"Чат: Ты тут?","language":"Японский","audioUrl":"/nte-meta/game-audio/ec1534db736e6026ed1f.ogg","sourceUrl":"","description":"Многих прямо трясёт, когда им пишут «ты тут?», прежде чем вообще объяснить, чего хотят. И если честно, твой ответ на вопрос «Ты тут?» во многом зависит от того, что именно собираются сказать дальше. Если это что-то, чего хочется избежать, в глубине души хочется просто исчезнуть из сети. Забавно всё-таки устроена человеческая психология, да?"},{"id":"ko-Play_Vo_Char_NPC030_about_003","title":"О Линко","language":"Корейский","audioUrl":"/nte-meta/game-audio/2c3e63dee2bb120e682e.ogg","sourceUrl":"","description":"Линко прямо места себе не находит из-за любых диссонирующих частот. Она всегда из кожи вон лезет, лишь бы мы не ссорились. Она до сих пор не понимает истинных причин, но есть большая вероятность, что со временем она подберётся вплотную к нашим секретам… И что мне делать, когда это случится? Неужели мне взаправду придётся выдать что-то вроде: «Ну и на чьей ты стороне — Экзе или моей?» Уф… какое же лицо она тогда состроит… И если честно, меня до безумия бесит, что я тут единственная, кто ломает над этим голову и составляет планы на экстренный случай."},{"id":"ko-Play_Vo_Char_NPC030_containment_002","title":"Сдерживание II","language":"Корейский","audioUrl":"/nte-meta/game-audio/5683934a7bab9f0e0466.ogg","sourceUrl":"","description":"В компаунде «Целено» можно завести друзей!"},{"id":"zh-Play_Vo_Char_NPC030_QTE_001","title":"Атака на входе I","language":"Китайский","audioUrl":"/nte-meta/game-audio/ff1b4bf86691a33c7c69.ogg","sourceUrl":"","description":"Бум!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_ZERO_002","title":"Особое переключение II — Ноль","language":"Китайский","audioUrl":"/nte-meta/game-audio/4dd069626e3fd4a653e7.ogg","sourceUrl":"","description":"Ладно, теперь моя очередь тебе помочь!"},{"id":"zh-Play_Vo_Char_NPC030_struck_001","title":"Урон I","language":"Китайский","audioUrl":"/nte-meta/game-audio/da4a3a725c4b0dae791d.ogg","sourceUrl":"","description":"Есть попадание."},{"id":"zh-Play_Vo_Char_NPC030_weather_002","title":"Дождливо","language":"Китайский","audioUrl":"/nte-meta/game-audio/a39169a3c07da11deb1e.ogg","sourceUrl":"","description":"А ведь дождевые капли… они ведь как телефонные провода между небом и землёй, правда?"},{"id":"en-Play_Vo_Char_NPC030_aoe_UI_001","title":"Сверхспособность I","language":"Английский","audioUrl":"/nte-meta/game-audio/f1f78ba7cb157212bbbc.ogg","sourceUrl":"","description":"Давай сегодня сыграем ещё раз!"},{"id":"en-Play_Vo_Char_NPC030_self_001","title":"Обо мне: работа","language":"Английский","audioUrl":"/nte-meta/game-audio/a8c6ca2ab0f6a0880d9b.ogg","sourceUrl":"","description":"Что касается Экзе, я проверяю его отчёты и переписываю всё, что совершенно не похоже на живую человеческую речь. Иногда я даже захожу под его аккаунтом, чтобы говорить от его имени или сглаживать углы в отношениях с другими отделами, которые он умудряется портить в одиночку и абсолютно непреднамеренно. Для Хаоса я синхронизирую разведданные прямо во время операций. А ещё я всегда наготове, чтобы проанализировать ключевые слова в его сообщениях, когда он упоминает какую-нибудь современную вещь, которую явно не знает, как назвать. С Линко я постоянно остаюсь на связи, чтобы подстраховать её в ту же секунду, как она окажется в изоляции. Я звоню ей без предупреждения, чтобы следить, вовремя ли она ложится, рано ли встаёт, идёт ли домой и не засиживается ли с ночи до утра. А ещё я созваниваюсь с её родителями, рассказываю о её успехах и вместе с ними нахваливаю их дочь…"},{"id":"ja-Play_Vo_Char_NPC030_dead_003","title":"Потеря сознания III","language":"Японский","audioUrl":"/nte-meta/game-audio/1ed3e0fb8f256b60c956.ogg","sourceUrl":"","description":"Всё исказилось… До скорого…"},{"id":"ja-Play_Vo_Char_NPC030_greet_002","title":"Дневное приветствие","language":"Японский","audioUrl":"/nte-meta/game-audio/b75bb4dc9632e5fc58d1.ogg","sourceUrl":"","description":"Сны во время полуденного отдыха обычно приятнее, чем ночные. Это потому, что они в буквальном смысле «дневные грёзы»?"},{"id":"ja-Play_Vo_Char_NPC030_Switch_002","title":"Переключение II","language":"Японский","audioUrl":"/nte-meta/game-audio/6dda5ec615dfe9f7c145.ogg","sourceUrl":"","description":"Подключилась — и я уже здесь!"},{"id":"ko-Play_Vo_Char_NPC030_Fly_001","title":"Планирование I","language":"Корейский","audioUrl":"/nte-meta/game-audio/18f50512616217029ded.ogg","sourceUrl":"","description":"Ю-ху-у! Лечу по ветру!"},{"id":"ko-Play_Vo_Char_NPC030_hstruck_001","title":"Сильный урон I","language":"Корейский","audioUrl":"/nte-meta/game-audio/bf8dbd7a4ca21a05686b.ogg","sourceUrl":"","description":"Данные повреждены."},{"id":"zh-Play_Vo_Char_NPC030_about_002","title":"О Хаосе","language":"Китайский","audioUrl":"/nte-meta/game-audio/2342fc53e97bf6222b00.ogg","sourceUrl":"","description":"Выбрать рингтон для Хаоса — та ещё головная боль. Чтобы связь добивала до передовой, мне нужно, чтобы он хватал трубку в ту же секунду, как услышит звонок. Если мелодия будет слишком мягкой, он её просто не заметит, когда увлечётся дракой или пойдёт по горячему следу цели. А если будет слишком громкой, он начнёт мне жаловаться… О! Придумала! Музыка, которая играет на экране победы в «Тетрамино»! Она ведь такая бодрая, да?"},{"id":"zh-Play_Vo_Char_NPC030_meet_001","title":"Первая встреча","language":"Китайский","audioUrl":"/nte-meta/game-audio/d369708cbb88996e5232.ogg","sourceUrl":"","description":"Привет-привет, это же я! Давненько не виделись, а? Как поживаешь?.. Я? Ну, на данный момент я лейтенант 6-го отряда ТОИ в ББА. Ха-ха, вот уж нежданчик, правда? Моё имя?.. Эй, только не говори, что не помнишь, как меня зовут!"},{"id":"ja-Play_Vo_Char_NPC030_greet_004","title":"Спокойной ночи","language":"Японский","audioUrl":"/nte-meta/game-audio/2338128161fcd8fa2aa7.ogg","sourceUrl":"","description":"Отдых необходим человеческому телу. Но стоит тебе заснуть, как разум теряет бдительность, и всё, что было похоронено в подсознании, всплывает наружу. Так что по-настоящему расслабиться всё равно не получается. Тяжело это."},{"id":"ko-Play_Vo_Char_NPC030_SSC_BC_001","title":"Особое переключение — Байканг","language":"Корейский","audioUrl":"/nte-meta/game-audio/cb39fd2c8b8e7ad67330.ogg","sourceUrl":"","description":"Байканг, ты что, и правда на работу пришёл?"},{"id":"zh-Play_Vo_Char_NPC030_dead_001","title":"Потеря сознания I","language":"Китайский","audioUrl":"/nte-meta/game-audio/9ac1f9a927587ce28089.ogg","sourceUrl":"","description":"Связь обрывается…"},{"id":"zh-Play_Vo_Char_NPC030_SSC_BC_001","title":"Особое переключение — Байканг","language":"Китайский","audioUrl":"/nte-meta/game-audio/0c21b0956bccb9b69b83.ogg","sourceUrl":"","description":"Байканг, ты что, и правда на работу пришёл?"},{"id":"zh-Play_Vo_Char_NPC030_talk_002","title":"Тема: Расследования","language":"Китайский","audioUrl":"/nte-meta/game-audio/6a816288944a94bcd76d.ogg","sourceUrl":"","description":"Я могла бы взять пример с Экзе и работать в тёмных уголках сети, где тебя никто не заметит… Но собирать инфу в открытых соцсетях — совсем другое дело. Только я могу без труда разговорить людей и добыть зацепки, которые двигают расследование вперёд. Когда у тебя есть друзья во всех сферах жизни, всё даётся проще. А если мне понадобится друг, я заведу его прямо на месте, ха-ха. Конечно, на людей не всегда можно положиться. Вот тут-то на сцену и выходит Линко. Она считывает важные эмоциональные подсказки. Как только мы фиксируем цель, в дело вступает Хаос. Обычно он выполняет приказы без особых проблем. Если всё пойдёт наперекосяк, я подключаюсь на помощь… Ну, если он, конечно, не забудет позвонить."},{"id":"en-Play_Vo_Char_NPC030_fh_001","title":"Исцеление I","language":"Английский","audioUrl":"/nte-meta/game-audio/470a404c75d5a1669491.ogg","sourceUrl":"","description":"Связь восстановилась!"},{"id":"en-Play_Vo_Char_NPC030_Switch_003","title":"Переключение III","language":"Английский","audioUrl":"/nte-meta/game-audio/3493cded987fbb677bca.ogg","sourceUrl":"","description":"С проекцией всё стабильно?"},{"id":"en-Play_Vo_Char_NPC030_TeammateDown_001","title":"Поражён товарищ по команде – ЭКЗЕ","language":"Английский","audioUrl":"/nte-meta/game-audio/e5e95532ba3ac9b759e2.ogg","sourceUrl":"","description":"На сегодня с тебя хватит… До завтра, хорошо?"},{"id":"zh-Play_Vo_Char_NPC030_aoe_UI_003","title":"Сверхспособность III","language":"Китайский","audioUrl":"/nte-meta/game-audio/132c6debdd790efe4722.ogg","sourceUrl":"","description":"Открываю сундук, достаю снаряжение!"},{"id":"zh-Play_Vo_Char_NPC030_windfall_003","title":"Неожиданная добыча III","language":"Китайский","audioUrl":"/nte-meta/game-audio/12edeafc3b6ae97d264d.ogg","sourceUrl":"","description":"Тебе это пригодится. Держи!"},{"id":"en-Play_Vo_Char_NPC030_greet_002","title":"Дневное приветствие","language":"Английский","audioUrl":"/nte-meta/game-audio/4b2beb87466380573d3e.ogg","sourceUrl":"","description":"Сны во время полуденного отдыха обычно приятнее, чем ночные. Это потому, что они в буквальном смысле «дневные грёзы»?"},{"id":"en-Play_Vo_Char_NPC030_skill_004","title":"Навык перенаправления IV","language":"Английский","audioUrl":"/nte-meta/game-audio/5b0e1458306837bff553.ogg","sourceUrl":"","description":"Ура, сигнал на максимуме!"},{"id":"ja-Play_Vo_Char_NPC030_weather_001","title":"Солнечно","language":"Японский","audioUrl":"/nte-meta/game-audio/ea56d956668cbc2ca905.ogg","sourceUrl":"","description":"В такую отличную погоду просто грех сидеть дома — надо выбраться куда-нибудь и забить день планами до отказа, верно?"},{"id":"ja-Play_Vo_Char_NPC030_windfall_001","title":"Неожиданная добыча I","language":"Японский","audioUrl":"/nte-meta/game-audio/5242eaf7cfa89580bb75.ogg","sourceUrl":"","description":"Может, позвонить кому-нибудь и узнать, кто это потерял?"},{"id":"ko-Play_Vo_Char_NPC030_meet_001","title":"Первая встреча","language":"Корейский","audioUrl":"/nte-meta/game-audio/ca36dd54c90a378ee05b.ogg","sourceUrl":"","description":"Привет-привет, это же я! Давненько не виделись, а? Как поживаешь?.. Я? Ну, на данный момент я лейтенант 6-го отряда ТОИ в ББА. Ха-ха, вот уж нежданчик, правда? Моё имя?.. Эй, только не говори, что не помнишь, как меня зовут!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_KES_002","title":"Особое переключение II — Хаос","language":"Корейский","audioUrl":"/nte-meta/game-audio/0c39dc41e636c1c5c684.ogg","sourceUrl":"","description":"Всю грязную работёнку оставляю тебе, бро!"},{"id":"ko-Play_Vo_Char_NPC030_windfall_002","title":"Неожиданная добыча II","language":"Корейский","audioUrl":"/nte-meta/game-audio/13772f9f4633d0f82aa5.ogg","sourceUrl":"","description":"Предмет найден, докладываю!"},{"id":"zh-Play_Vo_Char_NPC030_greet_003","title":"Вечернее приветствие","language":"Китайский","audioUrl":"/nte-meta/game-audio/769bf1dfdd16c9ca6c5c.ogg","sourceUrl":"","description":"Заходящее солнце… из-за него всегда кажется, будто пришло время прощаться с другом. От всей этой атмосферы становится так радостно и грустно одновременно."},{"id":"en-Play_Vo_Char_NPC030_chat_001","title":"Чат: Ты тут?","language":"Английский","audioUrl":"/nte-meta/game-audio/edb7749de221a1a940cd.ogg","sourceUrl":"","description":"Многих прямо трясёт, когда им пишут «ты тут?», прежде чем вообще объяснить, чего хотят. И если честно, твой ответ на вопрос «Ты тут?» во многом зависит от того, что именно собираются сказать дальше. Если это что-то, чего хочется избежать, в глубине души хочется просто исчезнуть из сети. Забавно всё-таки устроена человеческая психология, да?"},{"id":"en-Play_Vo_Char_NPC030_DodgeCombo_001","title":"Серия критических уклонений I","language":"Английский","audioUrl":"/nte-meta/game-audio/93e921d79c5f29138bf3.ogg","sourceUrl":"","description":"Ю-ху-ху!"},{"id":"en-Play_Vo_Char_NPC030_hp_002","title":"Низкий уровень здоровья II","language":"Английский","audioUrl":"/nte-meta/game-audio/3553919b80ca7bc8584b.ogg","sourceUrl":"","description":"Сигнал слабеет…"},{"id":"en-Play_Vo_Char_NPC030_SSC_AHQ_001","title":"Особое переключение — Лакримоза","language":"Английский","audioUrl":"/nte-meta/game-audio/988b578928d3c31a2b9c.ogg","sourceUrl":"","description":"Мозочка, можешь ещё немного поспать."},{"id":"en-Play_Vo_Char_NPC030_vexation_001","title":"Проблемы","language":"Английский","audioUrl":"/nte-meta/game-audio/135f624e456dc63e3e4f.ogg","sourceUrl":"","description":"Если меня что и беспокоит, то это, пожалуй, работа. Точнее, даже не сама работа, а отношения в коллективе… Но ты за меня не переживай. Пойми меня правильно, всё это серьёзно, просто… тут, наверное, уже ничего не исправишь, так что и переживать вообще нет смысла."},{"id":"en-Play_Vo_Char_NPC030_weather_004","title":"Жарко","language":"Английский","audioUrl":"/nte-meta/game-audio/8fbd8df0742c45feba15.ogg","sourceUrl":"","description":"Я тут по дороге мороженого прихватила. Держи! Это ведь твой любимый вкус, да?"},{"id":"en-Play_Vo_Char_NPC030_windfall_006","title":"Неожиданная добыча VI","language":"Английский","audioUrl":"/nte-meta/game-audio/34f3b937f6dab997b28b.ogg","sourceUrl":"","description":"Материалы для прокачки? А для какого персонажа?"},{"id":"ja-Play_Vo_Char_NPC030_gift_003","title":"Подарок получен III","language":"Японский","audioUrl":"/nte-meta/game-audio/8fa224b773942ed1a354.ogg","sourceUrl":"","description":"Ого, это что, маленький дружеский сюрприз?"},{"id":"ja-Play_Vo_Char_NPC030_skill_001","title":"Навык перенаправления I","language":"Японский","audioUrl":"/nte-meta/game-audio/1c896ce8f4cee8bdee5f.ogg","sourceUrl":"","description":"Друг, давай установим связь!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_EXE_002","title":"Особое переключение II — Экзе","language":"Японский","audioUrl":"/nte-meta/game-audio/41648598172957fdb76c.ogg","sourceUrl":"","description":"Это тебе самому пора ползти обратно в бэкенд!"},{"id":"ko-Play_Vo_Char_NPC030_gift_002","title":"Подарок получен II","language":"Корейский","audioUrl":"/nte-meta/game-audio/56b5ded38779d186a99c.ogg","sourceUrl":"","description":"Твой подарок хранит в себе твои чувства, и я их получила!"},{"id":"zh-Play_Vo_Char_NPC030_gift_003","title":"Подарок получен III","language":"Китайский","audioUrl":"/nte-meta/game-audio/5491bf68386f52764644.ogg","sourceUrl":"","description":"Ого, это что, маленький дружеский сюрприз?"},{"id":"en-Play_Vo_Char_NPC030_about_001","title":"Об ЭКЗЕ","language":"Английский","audioUrl":"/nte-meta/game-audio/f428b137077ecec2ab91.ogg","sourceUrl":"","description":"Дай-ка подумать… «1. С Экзе работа распределяется эффективно, что приносит выдающиеся результаты; 2. Наше ежедневное общение искренне и прямолинейно, обе стороны без стеснения высказывают всё, что считают нужным; 3. У каждой из сторон сформировалось глубокое понимание рабочего стиля, привычек и больных тем друг друга; Дополнительное примечание: обе стороны подтверждают, что на сегодняшний день никаких внутренних конфликтов по рабочим вопросам не возникало, и в будущем их не предвидится». …Хм-м, отлично, на этом и остановлюсь. Чистая правда, никакой лжи."},{"id":"en-Play_Vo_Char_NPC030_aoe_UI_002","title":"Сверхспособность II","language":"Английский","audioUrl":"/nte-meta/game-audio/e0f331fce1c2fb10c17b.ogg","sourceUrl":"","description":"Пора играть! Погнали!"},{"id":"en-Play_Vo_Char_NPC030_greet_004","title":"Спокойной ночи","language":"Английский","audioUrl":"/nte-meta/game-audio/329da4d85ff6a6584779.ogg","sourceUrl":"","description":"Отдых необходим человеческому телу. Но стоит тебе заснуть, как разум теряет бдительность, и всё, что было похоронено в подсознании, всплывает наружу. Так что по-настоящему расслабиться всё равно не получается. Тяжело это."},{"id":"ja-Play_Vo_Char_NPC030_TeammateDown_003","title":"Поражён товарищ по команде – Линко","language":"Японский","audioUrl":"/nte-meta/game-audio/7fe6157dd4c013b66d70.ogg","sourceUrl":"","description":"Всё в порядке. Наша связь не прервалась."},{"id":"ko-Play_Vo_Char_NPC030_deploy_001","title":"Отправка I","language":"Корейский","audioUrl":"/nte-meta/game-audio/ff7aafaa4255aa49aabc.ogg","sourceUrl":"","description":"Позвони мне — и я сразу буду рядом!"},{"id":"ko-Play_Vo_Char_NPC030_Fly_002","title":"Планирование II","language":"Корейский","audioUrl":"/nte-meta/game-audio/a8db9442f19bc9c0a7b4.ogg","sourceUrl":"","description":"Сливаюсь с воздухом!"},{"id":"ko-Play_Vo_Char_NPC030_Parry_002","title":"Парирование II","language":"Корейский","audioUrl":"/nte-meta/game-audio/105e24adeb376b7af14a.ogg","sourceUrl":"","description":"Достойный ответ."},{"id":"zh-Play_Vo_Char_NPC030_gift_002","title":"Подарок получен II","language":"Китайский","audioUrl":"/nte-meta/game-audio/7523133798903264100f.ogg","sourceUrl":"","description":"Твой подарок хранит в себе твои чувства, и я их получила!"},{"id":"zh-Play_Vo_Char_NPC030_windfall_002","title":"Неожиданная добыча II","language":"Китайский","audioUrl":"/nte-meta/game-audio/8c9bf01094ab8daf47f9.ogg","sourceUrl":"","description":"Предмет найден, докладываю!"},{"id":"en-Play_Vo_Char_NPC030_Fly_001","title":"Планирование I","language":"Английский","audioUrl":"/nte-meta/game-audio/05a9bfbf2cc651a25f89.ogg","sourceUrl":"","description":"Ю-ху-у! Лечу по ветру!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_EXE_001","title":"Особое переключение I — Экзе","language":"Японский","audioUrl":"/nte-meta/game-audio/4bf9e14db87a3cb4fa1c.ogg","sourceUrl":"","description":"Ого, Экзе, ты всё-таки вышел из своей комнаты!"},{"id":"zh-Play_Vo_Char_NPC030_struck_002","title":"Урон II","language":"Китайский","audioUrl":"/nte-meta/game-audio/fdb99e0eb856cc51d339.ogg","sourceUrl":"","description":"Небольшое возмущение…"},{"id":"ja-Play_Vo_Char_NPC030_TeammateDown_001","title":"Поражён товарищ по команде – ЭКЗЕ","language":"Японский","audioUrl":"/nte-meta/game-audio/3414bedb84bf272fd5b6.ogg","sourceUrl":"","description":"На сегодня с тебя хватит… До завтра, хорошо?"},{"id":"ko-Play_Vo_Char_NPC030_deploy_002","title":"Отправка II","language":"Корейский","audioUrl":"/nte-meta/game-audio/1a3fa4034bc9e766721a.ogg","sourceUrl":"","description":"Привет, старые и новые друзья!"},{"id":"ko-Play_Vo_Char_NPC030_hp_001","title":"Низкий уровень здоровья I","language":"Корейский","audioUrl":"/nte-meta/game-audio/7adeaaa8bc7917822044.ogg","sourceUrl":"","description":"Связь становится нестабильной…"},{"id":"en-Play_Vo_Char_NPC030_self_003","title":"Обо мне: Существование","language":"Английский","audioUrl":"/nte-meta/game-audio/676fd42fd86367c5fc2e.ogg","sourceUrl":"","description":"Существую ли я? Ты видишь модель персонажа, интерфейсы, текст, слышишь эту звуковую дорожку и прекрасно понимаешь, что всё это — лишь единицы и нули. Иллюзия, сотканная из цифр и сигналов. Так что, полагаю, для тебя в тот самый миг, когда всё это потеряет смысл, я с тем же успехом могла бы вообще никогда не существовать! А что до смысла, то он должен исходить из «причины» твоего бытия — из вопроса «почему» или «why» — буквы Y. Самое забавное, что с того самого мгновения, как я появилась на свет, у меня уже была моя «Y». И вот ответ на твой вопрос: «Да. Для себя я существую»."},{"id":"en-Play_Vo_Char_NPC030_SSC_FDY_001","title":"Особое переключение — Фадия","language":"Английский","audioUrl":"/nte-meta/game-audio/185b4c01bdfd0f74979f.ogg","sourceUrl":"","description":"Фадия, на тебя опять пожаловались?"},{"id":"ja-Play_Vo_Char_NPC030_skill_005","title":"Навык перенаправления V","language":"Японский","audioUrl":"/nte-meta/game-audio/2bbb9234bc020f04f43a.ogg","sourceUrl":"","description":"Пиу-пиу!"},{"id":"ko-Play_Vo_Char_NPC030_about_005","title":"О ТОИ-6","language":"Корейский","audioUrl":"/nte-meta/game-audio/d4d538b0625d9f7e410a.ogg","sourceUrl":"","description":"Бюро считает отряд из четырёх человек идеальным составом для подразделений ТОИ. Как только команда достигает этого числа, они больше никого не берут. Хм-м, думаешь, у нас и так тесновато? А Ница на очереди в резерв?.. Это всё потому, что квота не распространяется на напарников-аномалий. Вот Сяочжэнь, например, тоже не считается. Так что в нашем отряде всё ещё свободно одно место."},{"id":"ko-Play_Vo_Char_NPC030_ug_002","title":"Вознесение персонажа II","language":"Корейский","audioUrl":"/nte-meta/game-audio/cd1fb30858bcb862c666.ogg","sourceUrl":"","description":"Моя проекция стала чуть чётче?"},{"id":"zh-Play_Vo_Char_NPC030_QTE_003","title":"Атака на входе III","language":"Китайский","audioUrl":"/nte-meta/game-audio/4264d9d892368f39ac46.ogg","sourceUrl":"","description":"Привет!"},{"id":"en-Play_Vo_Char_NPC030_about_006","title":"О ТОИ-4","language":"Английский","audioUrl":"/nte-meta/game-audio/d2a172c6dd2fdbf5f045.ogg","sourceUrl":"","description":"Каждый раз, когда их отряд отправляется на задание, меня так и подмывает улыбнуться — до чего же они сплочённые ребята. В таких местах, как школа или работа, где людей вокруг себя не выбирают, иметь напарников, с которыми ты на одной волне, у которых те же интересы или которые просто понимают тебя с полуслова — о таком можно только мечтать."},{"id":"en-Play_Vo_Char_NPC030_deploy_002","title":"Отправка II","language":"Английский","audioUrl":"/nte-meta/game-audio/431c00a76711f225b24b.ogg","sourceUrl":"","description":"Привет, старые и новые друзья!"},{"id":"ja-Play_Vo_Char_NPC030_hobby_001","title":"Хобби","language":"Японский","audioUrl":"/nte-meta/game-audio/832f9c0690d8684331c3.ogg","sourceUrl":"","description":"Болтать с друзьями часами по телефону, переписываться по почте, слать голосовые, созваниваться по видео или просто строчить сообщения… У каждого из этих способов свой неповторимый вайб, и я обожаю абсолютно все варианты оставаться на связи! А вообще, у меня ещё куча самых разных увлечений… Ой, ну и видеоигры я просто обожаю!"},{"id":"ko-Play_Vo_Char_NPC030_containment_001","title":"Сдерживание I","language":"Корейский","audioUrl":"/nte-meta/game-audio/991556cc43ab100cdc20.ogg","sourceUrl":"","description":"Тебе одиноко? Продержись ещё немножко."},{"id":"en-Play_Vo_Char_NPC030_hstruck_002","title":"Сильный урон II","language":"Английский","audioUrl":"/nte-meta/game-audio/453c87ebfd670717db75.ogg","sourceUrl":"","description":"Сильные помехи."},{"id":"en-Play_Vo_Char_NPC030_SSC_LK_002","title":"Особое переключение II — Линко","language":"Английский","audioUrl":"/nte-meta/game-audio/61af1b1c466357ccb1cc.ogg","sourceUrl":"","description":"Давай я найду тебе какое-нибудь классное занятие!"}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"ko-Play_Vo_Char_NPC030_about_001","title":"Об ЭКЗЕ","language":"Корейский","audioUrl":"/nte-meta/game-audio/94721156e6858b47b413.ogg","sourceUrl":"","description":"Дай-ка подумать… «1. С Экзе работа распределяется эффективно, что приносит выдающиеся результаты; 2. Наше ежедневное общение искренне и прямолинейно, обе стороны без стеснения высказывают всё, что считают нужным; 3. У каждой из сторон сформировалось глубокое понимание рабочего стиля, привычек и больных тем друг друга; Дополнительное примечание: обе стороны подтверждают, что на сегодняшний день никаких внутренних конфликтов по рабочим вопросам не возникало, и в будущем их не предвидится». …Хм-м, отлично, на этом и остановлюсь. Чистая правда, никакой лжи."},{"id":"ko-Play_Vo_Char_NPC030_QTE_001","title":"Атака на входе I","language":"Корейский","audioUrl":"/nte-meta/game-audio/d34f07b368786943b1ab.ogg","sourceUrl":"","description":"Бум!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_ZH_001","title":"Особое переключение — Шинку","language":"Корейский","audioUrl":"/nte-meta/game-audio/50e1e321aa4273f2bb3e.ogg","sourceUrl":"","description":"Шинку, готова? Сделай глубокий вдох!"},{"id":"zh-Play_Vo_Char_NPC030_chat_002","title":"Чат: Начать разговор","language":"Китайский","audioUrl":"/nte-meta/game-audio/3b298d74a0b5063a0551.ogg","sourceUrl":"","description":"Как по мне, если уж начинать разговор, то надёжнее всего сразу переходить к делу и говорить всё как есть. Вот взять меня, к примеру — ха, я тут просто чтобы узнать, как ты! Случилось чего в последнее время, чем хочется поделиться с подругой? Хоть хорошее, хоть плохое — мне всё интересно!"},{"id":"zh-Play_Vo_Char_NPC030_fh_001","title":"Исцеление I","language":"Китайский","audioUrl":"/nte-meta/game-audio/665966ea4b89a6af714d.ogg","sourceUrl":"","description":"Связь восстановилась!"},{"id":"zh-Play_Vo_Char_NPC030_QTE_002","title":"Атака на входе II","language":"Китайский","audioUrl":"/nte-meta/game-audio/ce4d98c2a04378648679.ogg","sourceUrl":"","description":"Время пришло!"},{"id":"en-Play_Vo_Char_NPC030_anomaly_004","title":"Нуллификация II","language":"Английский","audioUrl":"/nte-meta/game-audio/e95ccbba41d24b2cfa03.ogg","sourceUrl":"","description":"Рада была познакомиться! Ещё увидимся!"},{"id":"ja-Play_Vo_Char_NPC030_deploy_002","title":"Отправка II","language":"Японский","audioUrl":"/nte-meta/game-audio/3d969db418e7f2764766.ogg","sourceUrl":"","description":"Привет, старые и новые друзья!"},{"id":"ja-Play_Vo_Char_NPC030_gift_004","title":"Подарок получен IV","language":"Японский","audioUrl":"/nte-meta/game-audio/d6c642c1484f7464ef52.ogg","sourceUrl":"","description":"Спасибо! Так, теперь мне надо придумать, что подарить тебе в ответ! Хм-м…"},{"id":"ja-Play_Vo_Char_NPC030_SSC_BH_001","title":"Особое переключение — Минт","language":"Японский","audioUrl":"/nte-meta/game-audio/87f328f637867bd37c3f.ogg","sourceUrl":"","description":"Эй, Минт, у меня для тебя сюрприз — небольшая викторина!"},{"id":"zh-Play_Vo_Char_NPC030_DodgeCombo_001","title":"Серия критических уклонений I","language":"Китайский","audioUrl":"/nte-meta/game-audio/8772be00c5a09af0a1f3.ogg","sourceUrl":"","description":"Ю-ху-ху!"},{"id":"zh-Play_Vo_Char_NPC030_Fly_001","title":"Планирование I","language":"Китайский","audioUrl":"/nte-meta/game-audio/6bbb7cdf807bdcde60f8.ogg","sourceUrl":"","description":"Ю-ху-у! Лечу по ветру!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_EXE_002","title":"Особое переключение II — Экзе","language":"Китайский","audioUrl":"/nte-meta/game-audio/e556d9e6978eef012d3d.ogg","sourceUrl":"","description":"Это тебе самому пора ползти обратно в бэкенд!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_KES_001","title":"Особое переключение I — Хаос","language":"Китайский","audioUrl":"/nte-meta/game-audio/8f56f0096efefd7b6f2b.ogg","sourceUrl":"","description":"Хаос, я прикрою!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_LK_002","title":"Особое переключение II — Линко","language":"Японский","audioUrl":"/nte-meta/game-audio/9485b4e6d659f6c9020d.ogg","sourceUrl":"","description":"Давай я найду тебе какое-нибудь классное занятие!"},{"id":"ko-Play_Vo_Char_NPC030_TeammateDown_002","title":"Поражён товарищ по команде — Хаос","language":"Корейский","audioUrl":"/nte-meta/game-audio/c12866b36a63d56d6841.ogg","sourceUrl":"","description":"Не время для последних слов. Это ещё не конец!"},{"id":"zh-Play_Vo_Char_NPC030_dead_002","title":"Потеря сознания II","language":"Китайский","audioUrl":"/nte-meta/game-audio/c8609fadbd669101a7d5.ogg","sourceUrl":"","description":"Прощай, мир."},{"id":"zh-Play_Vo_Char_NPC030_Switch_002","title":"Переключение II","language":"Китайский","audioUrl":"/nte-meta/game-audio/5f9025e1897efb42724a.ogg","sourceUrl":"","description":"Подключилась — и я уже здесь!"},{"id":"zh-Play_Vo_Char_NPC030_ug_003","title":"Вознесение персонажа III","language":"Китайский","audioUrl":"/nte-meta/game-audio/86461e0e4d76cc22778c.ogg","sourceUrl":"","description":"Такое чувство, будто я могу дозвониться в мгновение ока, даже туда, где вообще не ловит сеть."},{"id":"zh-Play_Vo_Char_NPC030_weather_004","title":"Жарко","language":"Китайский","audioUrl":"/nte-meta/game-audio/a72050b0c19dacbc2851.ogg","sourceUrl":"","description":"Я тут по дороге мороженого прихватила. Держи! Это ведь твой любимый вкус, да?"},{"id":"en-Play_Vo_Char_NPC030_skill_001","title":"Навык перенаправления I","language":"Английский","audioUrl":"/nte-meta/game-audio/9432830fa460fbffc01e.ogg","sourceUrl":"","description":"Друг, давай установим связь!"},{"id":"ja-Play_Vo_Char_NPC030_greet_001","title":"Утреннее приветствие","language":"Японский","audioUrl":"/nte-meta/game-audio/7965c5a727b4b3e39f38.ogg","sourceUrl":"","description":"«Доброе утречко», «Утречко», «Проснись и пой!», «Вставай, соня», «Просыпайся»… Между всеми ними столько нюансов. Как же это забавно…"},{"id":"ko-Play_Vo_Char_NPC030_about_002","title":"О Хаосе","language":"Корейский","audioUrl":"/nte-meta/game-audio/39f4c4548fe0142f4c80.ogg","sourceUrl":"","description":"Выбрать рингтон для Хаоса — та ещё головная боль. Чтобы связь добивала до передовой, мне нужно, чтобы он хватал трубку в ту же секунду, как услышит звонок. Если мелодия будет слишком мягкой, он её просто не заметит, когда увлечётся дракой или пойдёт по горячему следу цели. А если будет слишком громкой, он начнёт мне жаловаться… О! Придумала! Музыка, которая играет на экране победы в «Тетрамино»! Она ведь такая бодрая, да?"},{"id":"zh-Play_Vo_Char_NPC030_about_004","title":"О Бюро по борьбе с аномалиями","language":"Китайский","audioUrl":"/nte-meta/game-audio/7b6cbb3370044b0c83da.ogg","sourceUrl":"","description":"Бюро заключило со мной соглашение в первую очередь ради того, чтобы сдерживать меня и резко замедлить моё расширение. И лишь во вторую — чтобы использовать мои способности. Я прекрасно это понимаю, уж поверь. Но, несмотря на это, я с самого начала была рада помочь. Посуди самостоятельно: поддержание максимальной стабильности в обществе, от которого я завишу, — это как раз то, что позволяет каждому чувствовать себя в безопасности и копить прекрасные воспоминания с друзьями, верно?"},{"id":"zh-Play_Vo_Char_NPC030_windfall_004","title":"Неожиданная добыча IV","language":"Китайский","audioUrl":"/nte-meta/game-audio/bf6771c0a0482eb07d80.ogg","sourceUrl":"","description":"Ему будет одиноко, если его никто не подберёт."},{"id":"en-Play_Vo_Char_NPC030_hp_001","title":"Низкий уровень здоровья I","language":"Английский","audioUrl":"/nte-meta/game-audio/d1237ac0b97acb3573c0.ogg","sourceUrl":"","description":"Связь становится нестабильной…"},{"id":"en-Play_Vo_Char_NPC030_hstruck_001","title":"Сильный урон I","language":"Английский","audioUrl":"/nte-meta/game-audio/eddce144e96c29a513a8.ogg","sourceUrl":"","description":"Данные повреждены."},{"id":"en-Play_Vo_Char_NPC030_skill_002","title":"Навык перенаправления II","language":"Английский","audioUrl":"/nte-meta/game-audio/c4a33e03e9136af4b31f.ogg","sourceUrl":"","description":"Я тебе позвонила. Перезвони мне!"},{"id":"en-Play_Vo_Char_NPC030_struck_002","title":"Урон II","language":"Английский","audioUrl":"/nte-meta/game-audio/aef0b0dc32a45f3de2c3.ogg","sourceUrl":"","description":"Небольшое возмущение…"},{"id":"ko-Play_Vo_Char_NPC030_talk_002","title":"Тема: Расследования","language":"Корейский","audioUrl":"/nte-meta/game-audio/b7cfc3aaa1f23b1efe9f.ogg","sourceUrl":"","description":"Я могла бы взять пример с Экзе и работать в тёмных уголках сети, где тебя никто не заметит… Но собирать инфу в открытых соцсетях — совсем другое дело. Только я могу без труда разговорить людей и добыть зацепки, которые двигают расследование вперёд. Когда у тебя есть друзья во всех сферах жизни, всё даётся проще. А если мне понадобится друг, я заведу его прямо на месте, ха-ха. Конечно, на людей не всегда можно положиться. Вот тут-то на сцену и выходит Линко. Она считывает важные эмоциональные подсказки. Как только мы фиксируем цель, в дело вступает Хаос. Обычно он выполняет приказы без особых проблем. Если всё пойдёт наперекосяк, я подключаюсь на помощь… Ну, если он, конечно, не забудет позвонить."},{"id":"zh-Play_Vo_Char_NPC030_hp_002","title":"Низкий уровень здоровья II","language":"Китайский","audioUrl":"/nte-meta/game-audio/122a4eea3606aee11721.ogg","sourceUrl":"","description":"Сигнал слабеет…"},{"id":"zh-Play_Vo_Char_NPC030_SSC_AHQ_001","title":"Особое переключение — Лакримоза","language":"Китайский","audioUrl":"/nte-meta/game-audio/12a03aa7b07b1dbdc99b.ogg","sourceUrl":"","description":"Мозочка, можешь ещё немного поспать."},{"id":"zh-Play_Vo_Char_NPC030_windfall_005","title":"Неожиданная добыча V","language":"Китайский","audioUrl":"/nte-meta/game-audio/19a52a0f9400e106e4fe.ogg","sourceUrl":"","description":"Что для одного мусор, то для другого — сокровище."},{"id":"en-Play_Vo_Char_NPC030_TeammateDown_005","title":"Поражен товарищ по команде – Ноль","language":"Английский","audioUrl":"/nte-meta/game-audio/9949d8e35ca89150afe3.ogg","sourceUrl":"","description":"Мой друг в опасности? Так не пойдёт! Моя подруга в опасности? Так не пойдёт!"},{"id":"ja-Play_Vo_Char_NPC030_about_002","title":"О Хаосе","language":"Японский","audioUrl":"/nte-meta/game-audio/005135ca6330629c3be9.ogg","sourceUrl":"","description":"Выбрать рингтон для Хаоса — та ещё головная боль. Чтобы связь добивала до передовой, мне нужно, чтобы он хватал трубку в ту же секунду, как услышит звонок. Если мелодия будет слишком мягкой, он её просто не заметит, когда увлечётся дракой или пойдёт по горячему следу цели. А если будет слишком громкой, он начнёт мне жаловаться… О! Придумала! Музыка, которая играет на экране победы в «Тетрамино»! Она ведь такая бодрая, да?"},{"id":"ja-Play_Vo_Char_NPC030_Parry_002","title":"Парирование II","language":"Японский","audioUrl":"/nte-meta/game-audio/74fb1a89b0a41663c02f.ogg","sourceUrl":"","description":"Достойный ответ."},{"id":"en-Play_Vo_Char_NPC030_Switch_001","title":"Переключение I","language":"Английский","audioUrl":"/nte-meta/game-audio/b56daa4a84b3c66a1169.ogg","sourceUrl":"","description":"Моя проекция уже здесь!"},{"id":"ja-Play_Vo_Char_NPC030_fh_002","title":"Исцеление II","language":"Японский","audioUrl":"/nte-meta/game-audio/5828f481d308207e700f.ogg","sourceUrl":"","description":"Системы восстанавливаются."},{"id":"ja-Play_Vo_Char_NPC030_windfall_004","title":"Неожиданная добыча IV","language":"Японский","audioUrl":"/nte-meta/game-audio/e68a09d0b5450c6a0826.ogg","sourceUrl":"","description":"Ему будет одиноко, если его никто не подберёт."},{"id":"ko-Play_Vo_Char_NPC030_weather_003","title":"Холодно","language":"Корейский","audioUrl":"/nte-meta/game-audio/e053a260ec4a73234065.ogg","sourceUrl":"","description":"На, держи. Только что взяла в отделе горячих напитков. Самое то, чтобы согреть руки."},{"id":"zh-Play_Vo_Char_NPC030_self_002","title":"Обо мне: Общение","language":"Китайский","audioUrl":"/nte-meta/game-audio/3ff661d9760afde3a275.ogg","sourceUrl":"","description":"Закрытую связь нашего отряда настраивает не Чуппа, это моя собственная специальная сборка. В основу системы я заложила «людей и их социальные связи». Плюс в том, что она может передавать не только голос, но и генерировать объекты прямо на месте — включая моих аватаров или инструменты, которые экспортирует Экзе. Минус — она почти не работает в безлюдных зонах далеко за городом или внутри аномальных измерений, отрезанных от сети. О, но если тебе кровь из носу нужно будет связаться со мной в каком-нибудь подобном месте, есть способ хлопотнее: тебе придётся ненадолго погрузиться в собственное подсознание…"},{"id":"zh-Play_Vo_Char_NPC030_skill_002","title":"Навык перенаправления II","language":"Китайский","audioUrl":"/nte-meta/game-audio/b4766bcdd2a9a315c4cc.ogg","sourceUrl":"","description":"Я тебе позвонила. Перезвони мне!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_YLY_001","title":"Особое переключение: Ирой","language":"Китайский","audioUrl":"/nte-meta/game-audio/358a78cefa19c74d7baf.ogg","sourceUrl":"","description":"Передай привет ребяткам в своих снах!"},{"id":"en-Play_Vo_Char_NPC030_SSC_YLY_001","title":"Особое переключение: Ирой","language":"Английский","audioUrl":"/nte-meta/game-audio/76c82f1b4ab622c0cf8b.ogg","sourceUrl":"","description":"Передай привет ребяткам в своих снах!"},{"id":"en-Play_Vo_Char_NPC030_weather_003","title":"Холодно","language":"Английский","audioUrl":"/nte-meta/game-audio/993ce37f2518e6adb1a6.ogg","sourceUrl":"","description":"На, держи. Только что взяла в отделе горячих напитков. Самое то, чтобы согреть руки."},{"id":"ja-Play_Vo_Char_NPC030_gift_002","title":"Подарок получен II","language":"Японский","audioUrl":"/nte-meta/game-audio/e6d9a26a70fd86baa49e.ogg","sourceUrl":"","description":"Твой подарок хранит в себе твои чувства, и я их получила!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_YI_001","title":"Особое переключение — Ския","language":"Японский","audioUrl":"/nte-meta/game-audio/72ac683a92eaf80da7f8.ogg","sourceUrl":"","description":"Ския, не переживай, я возьму это на себя."},{"id":"ko-Play_Vo_Char_NPC030_dead_003","title":"Потеря сознания III","language":"Корейский","audioUrl":"/nte-meta/game-audio/c27907f8c1105d44163e.ogg","sourceUrl":"","description":"Всё исказилось… До скорого…"},{"id":"ko-Play_Vo_Char_NPC030_QTE_003","title":"Атака на входе III","language":"Корейский","audioUrl":"/nte-meta/game-audio/18c7f113f5c9802b0a9a.ogg","sourceUrl":"","description":"Привет!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_BH_001","title":"Особое переключение — Минт","language":"Корейский","audioUrl":"/nte-meta/game-audio/488ee0bf570e750d7aab.ogg","sourceUrl":"","description":"Эй, Минт, у меня для тебя сюрприз — небольшая викторина!"},{"id":"zh-Play_Vo_Char_NPC030_dead_003","title":"Потеря сознания III","language":"Китайский","audioUrl":"/nte-meta/game-audio/155f82efca3fe196ff88.ogg","sourceUrl":"","description":"Всё исказилось… До скорого…"},{"id":"zh-Play_Vo_Char_NPC030_vexation_001","title":"Проблемы","language":"Китайский","audioUrl":"/nte-meta/game-audio/5222f8fb050bba2d2d31.ogg","sourceUrl":"","description":"Если меня что и беспокоит, то это, пожалуй, работа. Точнее, даже не сама работа, а отношения в коллективе… Но ты за меня не переживай. Пойми меня правильно, всё это серьёзно, просто… тут, наверное, уже ничего не исправишь, так что и переживать вообще нет смысла."},{"id":"en-Play_Vo_Char_NPC030_containment_001","title":"Сдерживание I","language":"Английский","audioUrl":"/nte-meta/game-audio/c14828d0e1ea41e211a7.ogg","sourceUrl":"","description":"Тебе одиноко? Продержись ещё немножко."},{"id":"en-Play_Vo_Char_NPC030_deploy_001","title":"Отправка I","language":"Английский","audioUrl":"/nte-meta/game-audio/1be15910deb1a20700d0.ogg","sourceUrl":"","description":"Позвони мне — и я сразу буду рядом!"},{"id":"en-Play_Vo_Char_NPC030_gift_001","title":"Подарок получен I","language":"Английский","audioUrl":"/nte-meta/game-audio/0384fcf29647f45542d0.ogg","sourceUrl":"","description":"Какой классный подарок! Надо бы найти ему местечко…"},{"id":"ja-Play_Vo_Char_NPC030_containment_002","title":"Сдерживание II","language":"Японский","audioUrl":"/nte-meta/game-audio/6d04678100c23f9a92e9.ogg","sourceUrl":"","description":"В компаунде «Целено» можно завести друзей!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_ZERO_001","title":"Особое переключение I — Ноль","language":"Японский","audioUrl":"/nte-meta/game-audio/97ab38ebd19e4026cbf8.ogg","sourceUrl":"","description":"Оценщик, мы на одной волне! Оценщица, мы на одной волне!"},{"id":"ko-Play_Vo_Char_NPC030_fh_001","title":"Исцеление I","language":"Корейский","audioUrl":"/nte-meta/game-audio/4579dda75c0497034875.ogg","sourceUrl":"","description":"Связь восстановилась!"},{"id":"ko-Play_Vo_Char_NPC030_gift_004","title":"Подарок получен IV","language":"Корейский","audioUrl":"/nte-meta/game-audio/ade328aa45d1dbedccdb.ogg","sourceUrl":"","description":"Спасибо! Так, теперь мне надо придумать, что подарить тебе в ответ! Хм-м…"},{"id":"zh-Play_Vo_Char_NPC030_SSC_LK_001","title":"Особое переключение I — Линко","language":"Китайский","audioUrl":"/nte-meta/game-audio/5be6d402618d2a67b35a.ogg","sourceUrl":"","description":"Линко, подключайся и меняемся!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_LK_002","title":"Особое переключение II — Линко","language":"Китайский","audioUrl":"/nte-meta/game-audio/e7ac3a39002898450553.ogg","sourceUrl":"","description":"Давай я найду тебе какое-нибудь классное занятие!"},{"id":"en-Play_Vo_Char_NPC030_aoe_UI_003","title":"Сверхспособность III","language":"Английский","audioUrl":"/nte-meta/game-audio/787cd03b333a04bb793e.ogg","sourceUrl":"","description":"Открываю сундук, достаю снаряжение!"},{"id":"en-Play_Vo_Char_NPC030_SSC_LK_001","title":"Особое переключение I — Линко","language":"Английский","audioUrl":"/nte-meta/game-audio/5b51c4355f97f906d290.ogg","sourceUrl":"","description":"Линко, подключайся и меняемся!"},{"id":"ja-Play_Vo_Char_NPC030_weather_002","title":"Дождливо","language":"Японский","audioUrl":"/nte-meta/game-audio/eca19f2fef9a9e50e2d3.ogg","sourceUrl":"","description":"А ведь дождевые капли… они ведь как телефонные провода между небом и землёй, правда?"},{"id":"zh-Play_Vo_Char_NPC030_windfall_006","title":"Неожиданная добыча VI","language":"Китайский","audioUrl":"/nte-meta/game-audio/f58e76cbf264b61666a1.ogg","sourceUrl":"","description":"Материалы для прокачки? А для какого персонажа?"},{"id":"en-Play_Vo_Char_NPC030_hobby_001","title":"Хобби","language":"Английский","audioUrl":"/nte-meta/game-audio/e90b0160d03520a35c0e.ogg","sourceUrl":"","description":"Болтать с друзьями часами по телефону, переписываться по почте, слать голосовые, созваниваться по видео или просто строчить сообщения… У каждого из этих способов свой неповторимый вайб, и я обожаю абсолютно все варианты оставаться на связи! А вообще, у меня ещё куча самых разных увлечений… Ой, ну и видеоигры я просто обожаю!"},{"id":"en-Play_Vo_Char_NPC030_SSC_BC_001","title":"Особое переключение — Байканг","language":"Английский","audioUrl":"/nte-meta/game-audio/140c2306848359d9f0fc.ogg","sourceUrl":"","description":"Байканг, ты что, и правда на работу пришёл?"},{"id":"en-Play_Vo_Char_NPC030_SSC_KES_001","title":"Особое переключение I — Хаос","language":"Английский","audioUrl":"/nte-meta/game-audio/e36fc5c690b9e5b259fa.ogg","sourceUrl":"","description":"Хаос, я прикрою!"},{"id":"en-Play_Vo_Char_NPC030_Switch_002","title":"Переключение II","language":"Английский","audioUrl":"/nte-meta/game-audio/f0dea89893c050521d9f.ogg","sourceUrl":"","description":"Подключилась — и я уже здесь!"},{"id":"ja-Play_Vo_Char_NPC030_Switch_001","title":"Переключение I","language":"Японский","audioUrl":"/nte-meta/game-audio/3e789d1e33d46edcdc22.ogg","sourceUrl":"","description":"Моя проекция уже здесь!"},{"id":"ko-Play_Vo_Char_NPC030_skill_002","title":"Навык перенаправления II","language":"Корейский","audioUrl":"/nte-meta/game-audio/c08d08866642e1bba5c8.ogg","sourceUrl":"","description":"Я тебе позвонила. Перезвони мне!"},{"id":"ko-Play_Vo_Char_NPC030_Switch_001","title":"Переключение I","language":"Корейский","audioUrl":"/nte-meta/game-audio/4f6e8e8b992f3f7de2e7.ogg","sourceUrl":"","description":"Моя проекция уже здесь!"},{"id":"zh-Play_Vo_Char_NPC030_about_005","title":"О ТОИ-6","language":"Китайский","audioUrl":"/nte-meta/game-audio/54de4d54d5c6052b79ed.ogg","sourceUrl":"","description":"Бюро считает отряд из четырёх человек идеальным составом для подразделений ТОИ. Как только команда достигает этого числа, они больше никого не берут. Хм-м, думаешь, у нас и так тесновато? А Ница на очереди в резерв?.. Это всё потому, что квота не распространяется на напарников-аномалий. Вот Сяочжэнь, например, тоже не считается. Так что в нашем отряде всё ещё свободно одно место."},{"id":"zh-Play_Vo_Char_NPC030_SSC_EXE_001","title":"Особое переключение I — Экзе","language":"Китайский","audioUrl":"/nte-meta/game-audio/314d16aabbfa710da55a.ogg","sourceUrl":"","description":"Ого, Экзе, ты всё-таки вышел из своей комнаты!"},{"id":"en-Play_Vo_Char_NPC030_QTE_003","title":"Атака на входе III","language":"Английский","audioUrl":"/nte-meta/game-audio/86e54ee813b062467d51.ogg","sourceUrl":"","description":"Привет!"},{"id":"en-Play_Vo_Char_NPC030_SSC_ZERO_001","title":"Особое переключение I — Ноль","language":"Английский","audioUrl":"/nte-meta/game-audio/b235e7c95c584ca28f71.ogg","sourceUrl":"","description":"Оценщик, мы на одной волне! Оценщица, мы на одной волне!"},{"id":"ja-Play_Vo_Char_NPC030_struck_001","title":"Урон I","language":"Японский","audioUrl":"/nte-meta/game-audio/7342ff1ae1b9b3d6460f.ogg","sourceUrl":"","description":"Есть попадание."},{"id":"ko-Play_Vo_Char_NPC030_skill_004","title":"Навык перенаправления IV","language":"Корейский","audioUrl":"/nte-meta/game-audio/df13204d927288030d7c.ogg","sourceUrl":"","description":"Ура, сигнал на максимуме!"},{"id":"ko-Play_Vo_Char_NPC030_TeammateDown_001","title":"Поражён товарищ по команде – ЭКЗЕ","language":"Корейский","audioUrl":"/nte-meta/game-audio/9d527f5eb1fa7b64a50e.ogg","sourceUrl":"","description":"На сегодня с тебя хватит… До завтра, хорошо?"},{"id":"ko-Play_Vo_Char_NPC030_windfall_004","title":"Неожиданная добыча IV","language":"Корейский","audioUrl":"/nte-meta/game-audio/d08fd744860edda1f735.ogg","sourceUrl":"","description":"Ему будет одиноко, если его никто не подберёт."},{"id":"zh-Play_Vo_Char_NPC030_SSC_KES_002","title":"Особое переключение II — Хаос","language":"Китайский","audioUrl":"/nte-meta/game-audio/7798044776a2196ea623.ogg","sourceUrl":"","description":"Всю грязную работёнку оставляю тебе, бро!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_ZH_001","title":"Особое переключение — Шинку","language":"Китайский","audioUrl":"/nte-meta/game-audio/fcc847aeddc9654af83b.ogg","sourceUrl":"","description":"Шинку, готова? Сделай глубокий вдох!"},{"id":"en-Play_Vo_Char_NPC030_skill_003","title":"Навык перенаправления III","language":"Английский","audioUrl":"/nte-meta/game-audio/bd170f786ab1b02dc789.ogg","sourceUrl":"","description":"Запомни этот номер!"},{"id":"ja-Play_Vo_Char_NPC030_QTE_002","title":"Атака на входе II","language":"Японский","audioUrl":"/nte-meta/game-audio/6bf53099a8affe932112.ogg","sourceUrl":"","description":"Время пришло!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_KES_001","title":"Особое переключение I — Хаос","language":"Японский","audioUrl":"/nte-meta/game-audio/f032a7403a60b161a412.ogg","sourceUrl":"","description":"Хаос, я прикрою!"},{"id":"zh-Play_Vo_Char_NPC030_greet_002","title":"Дневное приветствие","language":"Китайский","audioUrl":"/nte-meta/game-audio/d3d3a867f074c71fc11a.ogg","sourceUrl":"","description":"Сны во время полуденного отдыха обычно приятнее, чем ночные. Это потому, что они в буквальном смысле «дневные грёзы»?"},{"id":"zh-Play_Vo_Char_NPC030_TeammateDown_005","title":"Поражен товарищ по команде – Ноль","language":"Китайский","audioUrl":"/nte-meta/game-audio/747c992195594cdaea67.ogg","sourceUrl":"","description":"Мой друг в опасности? Так не пойдёт! Моя подруга в опасности? Так не пойдёт!"},{"id":"en-Play_Vo_Char_NPC030_gift_002","title":"Подарок получен II","language":"Английский","audioUrl":"/nte-meta/game-audio/69205b1c1ae91f2cfa2a.ogg","sourceUrl":"","description":"Твой подарок хранит в себе твои чувства, и я их получила!"},{"id":"en-Play_Vo_Char_NPC030_windfall_003","title":"Неожиданная добыча III","language":"Английский","audioUrl":"/nte-meta/game-audio/3957d9e22a72442681ce.ogg","sourceUrl":"","description":"Тебе это пригодится. Держи!"},{"id":"ja-Play_Vo_Char_NPC030_struck_002","title":"Урон II","language":"Японский","audioUrl":"/nte-meta/game-audio/f576ec1807483a8037f2.ogg","sourceUrl":"","description":"Небольшое возмущение…"},{"id":"ja-Play_Vo_Char_NPC030_windfall_005","title":"Неожиданная добыча V","language":"Японский","audioUrl":"/nte-meta/game-audio/d81802b1f4555bf12ab9.ogg","sourceUrl":"","description":"Что для одного мусор, то для другого — сокровище."},{"id":"ko-Play_Vo_Char_NPC030_about_006","title":"О ТОИ-4","language":"Корейский","audioUrl":"/nte-meta/game-audio/b45f375871789dc0d70f.ogg","sourceUrl":"","description":"Каждый раз, когда их отряд отправляется на задание, меня так и подмывает улыбнуться — до чего же они сплочённые ребята. В таких местах, как школа или работа, где людей вокруг себя не выбирают, иметь напарников, с которыми ты на одной волне, у которых те же интересы или которые просто понимают тебя с полуслова — о таком можно только мечтать."},{"id":"ko-Play_Vo_Char_NPC030_chat_003","title":"Чат: Продолжить общение","language":"Корейский","audioUrl":"/nte-meta/game-audio/09927d1424f1c958c112.ogg","sourceUrl":"","description":"Некоторые люди так боятся неловкого молчания, что вообще не решаются заговорить. Звучит немного парадоксально, но понять их можно. В таких случаях приходится считывать атмосферу, чтобы сообразить, куда повернуть беседу. Безопаснее всего переключиться на что-то банальное вроде погоды или свежих новостей. Хотя и это может выйти боком… Иногда просто не везёт…"},{"id":"zh-Play_Vo_Char_NPC030_skill_004","title":"Навык перенаправления IV","language":"Китайский","audioUrl":"/nte-meta/game-audio/6ddf8ad8dc559a40c6f3.ogg","sourceUrl":"","description":"Ура, сигнал на максимуме!"},{"id":"en-Play_Vo_Char_NPC030_kill_001","title":"Убийство I","language":"Английский","audioUrl":"/nte-meta/game-audio/0f8d1bb5f01192e9ae0d.ogg","sourceUrl":"","description":"Я буду помнить тебя."},{"id":"zh-Play_Vo_Char_NPC030_hp_001","title":"Низкий уровень здоровья I","language":"Китайский","audioUrl":"/nte-meta/game-audio/2e121c5a4375249d6e15.ogg","sourceUrl":"","description":"Связь становится нестабильной…"},{"id":"ja-Play_Vo_Char_NPC030_about_006","title":"О ТОИ-4","language":"Японский","audioUrl":"/nte-meta/game-audio/b314263d136256f06525.ogg","sourceUrl":"","description":"Каждый раз, когда их отряд отправляется на задание, меня так и подмывает улыбнуться — до чего же они сплочённые ребята. В таких местах, как школа или работа, где людей вокруг себя не выбирают, иметь напарников, с которыми ты на одной волне, у которых те же интересы или которые просто понимают тебя с полуслова — о таком можно только мечтать."},{"id":"ja-Play_Vo_Char_NPC030_anomaly_004","title":"Нуллификация II","language":"Японский","audioUrl":"/nte-meta/game-audio/ab25d102113a4194a052.ogg","sourceUrl":"","description":"Рада была познакомиться! Ещё увидимся!"},{"id":"ja-Play_Vo_Char_NPC030_chat_002","title":"Чат: Начать разговор","language":"Японский","audioUrl":"/nte-meta/game-audio/475a08756858c1a363fc.ogg","sourceUrl":"","description":"Как по мне, если уж начинать разговор, то надёжнее всего сразу переходить к делу и говорить всё как есть. Вот взять меня, к примеру — ха, я тут просто чтобы узнать, как ты! Случилось чего в последнее время, чем хочется поделиться с подругой? Хоть хорошее, хоть плохое — мне всё интересно!"},{"id":"ko-Play_Vo_Char_NPC030_self_002","title":"Обо мне: Общение","language":"Корейский","audioUrl":"/nte-meta/game-audio/cf9bddd9f4524c9bab10.ogg","sourceUrl":"","description":"Закрытую связь нашего отряда настраивает не Чуппа, это моя собственная специальная сборка. В основу системы я заложила «людей и их социальные связи». Плюс в том, что она может передавать не только голос, но и генерировать объекты прямо на месте — включая моих аватаров или инструменты, которые экспортирует Экзе. Минус — она почти не работает в безлюдных зонах далеко за городом или внутри аномальных измерений, отрезанных от сети. О, но если тебе кровь из носу нужно будет связаться со мной в каком-нибудь подобном месте, есть способ хлопотнее: тебе придётся ненадолго погрузиться в собственное подсознание…"},{"id":"ko-Play_Vo_Char_NPC030_struck_001","title":"Урон I","language":"Корейский","audioUrl":"/nte-meta/game-audio/e66bfeda84573048c6da.ogg","sourceUrl":"","description":"Есть попадание."},{"id":"ko-Play_Vo_Char_NPC030_weather_004","title":"Жарко","language":"Корейский","audioUrl":"/nte-meta/game-audio/a0fff51912a86aa10534.ogg","sourceUrl":"","description":"Я тут по дороге мороженого прихватила. Держи! Это ведь твой любимый вкус, да?"},{"id":"zh-Play_Vo_Char_NPC030_fh_002","title":"Исцеление II","language":"Китайский","audioUrl":"/nte-meta/game-audio/b2c39088a68749ffdf24.ogg","sourceUrl":"","description":"Системы восстанавливаются."},{"id":"zh-Play_Vo_Char_NPC030_greet_004","title":"Спокойной ночи","language":"Китайский","audioUrl":"/nte-meta/game-audio/c3cc9d410e3680cc0248.ogg","sourceUrl":"","description":"Отдых необходим человеческому телу. Но стоит тебе заснуть, как разум теряет бдительность, и всё, что было похоронено в подсознании, всплывает наружу. Так что по-настоящему расслабиться всё равно не получается. Тяжело это."},{"id":"zh-Play_Vo_Char_NPC030_hobby_001","title":"Хобби","language":"Китайский","audioUrl":"/nte-meta/game-audio/8a985564a2632c6c66c3.ogg","sourceUrl":"","description":"Болтать с друзьями часами по телефону, переписываться по почте, слать голосовые, созваниваться по видео или просто строчить сообщения… У каждого из этих способов свой неповторимый вайб, и я обожаю абсолютно все варианты оставаться на связи! А вообще, у меня ещё куча самых разных увлечений… Ой, ну и видеоигры я просто обожаю!"},{"id":"en-Play_Vo_Char_NPC030_anomaly_003","title":"Нуллификация I","language":"Английский","audioUrl":"/nte-meta/game-audio/ae3fdbd0e5eab80621c3.ogg","sourceUrl":"","description":"Пора тебе возвращаться обратно в море."},{"id":"ja-Play_Vo_Char_NPC030_anomaly_003","title":"Нуллификация I","language":"Японский","audioUrl":"/nte-meta/game-audio/48892cd2c029072822ca.ogg","sourceUrl":"","description":"Пора тебе возвращаться обратно в море."},{"id":"ja-Play_Vo_Char_NPC030_Fly_001","title":"Планирование I","language":"Японский","audioUrl":"/nte-meta/game-audio/55738932517984d1d4ae.ogg","sourceUrl":"","description":"Ю-ху-у! Лечу по ветру!"},{"id":"ko-Play_Vo_Char_NPC030_TeammateDown_003","title":"Поражён товарищ по команде – Линко","language":"Корейский","audioUrl":"/nte-meta/game-audio/9633a2392e9febd42101.ogg","sourceUrl":"","description":"Всё в порядке. Наша связь не прервалась."},{"id":"zh-Play_Vo_Char_NPC030_skill_003","title":"Навык перенаправления III","language":"Китайский","audioUrl":"/nte-meta/game-audio/c21ace3d39e49e6bf008.ogg","sourceUrl":"","description":"Запомни этот номер!"},{"id":"en-Play_Vo_Char_NPC030_SSC_BH_001","title":"Особое переключение — Минт","language":"Английский","audioUrl":"/nte-meta/game-audio/8ad7466cfae90d308aae.ogg","sourceUrl":"","description":"Эй, Минт, у меня для тебя сюрприз — небольшая викторина!"},{"id":"en-Play_Vo_Char_NPC030_windfall_002","title":"Неожиданная добыча II","language":"Английский","audioUrl":"/nte-meta/game-audio/81db9e9c8fbd918336d3.ogg","sourceUrl":"","description":"Предмет найден, докладываю!"},{"id":"ja-Play_Vo_Char_NPC030_greet_003","title":"Вечернее приветствие","language":"Японский","audioUrl":"/nte-meta/game-audio/b3278a7a66277a8a9612.ogg","sourceUrl":"","description":"Заходящее солнце… из-за него всегда кажется, будто пришло время прощаться с другом. От всей этой атмосферы становится так радостно и грустно одновременно."},{"id":"ja-Play_Vo_Char_NPC030_SSC_BC_001","title":"Особое переключение — Байканг","language":"Японский","audioUrl":"/nte-meta/game-audio/c0b895e5c9fecec3eda1.ogg","sourceUrl":"","description":"Байканг, ты что, и правда на работу пришёл?"},{"id":"ja-Play_Vo_Char_NPC030_SSC_KES_002","title":"Особое переключение II — Хаос","language":"Японский","audioUrl":"/nte-meta/game-audio/8dfe69a3b178a232b632.ogg","sourceUrl":"","description":"Всю грязную работёнку оставляю тебе, бро!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_LK_001","title":"Особое переключение I — Линко","language":"Японский","audioUrl":"/nte-meta/game-audio/30aa81c7c79e3de5bb92.ogg","sourceUrl":"","description":"Линко, подключайся и меняемся!"},{"id":"ko-Play_Vo_Char_NPC030_QTE_002","title":"Атака на входе II","language":"Корейский","audioUrl":"/nte-meta/game-audio/c15b7947854e21784f57.ogg","sourceUrl":"","description":"Время пришло!"},{"id":"ja-Play_Vo_Char_NPC030_dead_002","title":"Потеря сознания II","language":"Японский","audioUrl":"/nte-meta/game-audio/7cabe313e5a1dc9fab89.ogg","sourceUrl":"","description":"Прощай, мир."},{"id":"ja-Play_Vo_Char_NPC030_weather_004","title":"Жарко","language":"Японский","audioUrl":"/nte-meta/game-audio/70d7a9a0a049e7aaae0f.ogg","sourceUrl":"","description":"Я тут по дороге мороженого прихватила. Держи! Это ведь твой любимый вкус, да?"},{"id":"ko-Play_Vo_Char_NPC030_about_004","title":"О Бюро по борьбе с аномалиями","language":"Корейский","audioUrl":"/nte-meta/game-audio/025c4c45abe49427e0e0.ogg","sourceUrl":"","description":"Бюро заключило со мной соглашение в первую очередь ради того, чтобы сдерживать меня и резко замедлить моё расширение. И лишь во вторую — чтобы использовать мои способности. Я прекрасно это понимаю, уж поверь. Но, несмотря на это, я с самого начала была рада помочь. Посуди самостоятельно: поддержание максимальной стабильности в обществе, от которого я завишу, — это как раз то, что позволяет каждому чувствовать себя в безопасности и копить прекрасные воспоминания с друзьями, верно?"},{"id":"ko-Play_Vo_Char_NPC030_SSC_YLY_001","title":"Особое переключение: Ирой","language":"Корейский","audioUrl":"/nte-meta/game-audio/bf098e0b961ac5ecd2ea.ogg","sourceUrl":"","description":"Передай привет ребяткам в своих снах!"},{"id":"zh-Play_Vo_Char_NPC030_containment_002","title":"Сдерживание II","language":"Китайский","audioUrl":"/nte-meta/game-audio/41e783935ef6ef59fe16.ogg","sourceUrl":"","description":"В компаунде «Целено» можно завести друзей!"},{"id":"en-Play_Vo_Char_NPC030_SSC_EXE_001","title":"Особое переключение I — Экзе","language":"Английский","audioUrl":"/nte-meta/game-audio/7f0c4328444d16568479.ogg","sourceUrl":"","description":"Ого, Экзе, ты всё-таки вышел из своей комнаты!"},{"id":"ja-Play_Vo_Char_NPC030_DodgeCombo_002","title":"Серия критических уклонений II","language":"Японский","audioUrl":"/nte-meta/game-audio/e3e76b64ebee3b90135d.ogg","sourceUrl":"","description":"Просто шажок в сторону."},{"id":"ja-Play_Vo_Char_NPC030_self_002","title":"Обо мне: Общение","language":"Японский","audioUrl":"/nte-meta/game-audio/3ca6954bebc0df3f8c78.ogg","sourceUrl":"","description":"Закрытую связь нашего отряда настраивает не Чуппа, это моя собственная специальная сборка. В основу системы я заложила «людей и их социальные связи». Плюс в том, что она может передавать не только голос, но и генерировать объекты прямо на месте — включая моих аватаров или инструменты, которые экспортирует Экзе. Минус — она почти не работает в безлюдных зонах далеко за городом или внутри аномальных измерений, отрезанных от сети. О, но если тебе кровь из носу нужно будет связаться со мной в каком-нибудь подобном месте, есть способ хлопотнее: тебе придётся ненадолго погрузиться в собственное подсознание…"},{"id":"ko-Play_Vo_Char_NPC030_chat_001","title":"Чат: Ты тут?","language":"Корейский","audioUrl":"/nte-meta/game-audio/ea47f2f8f92ba271e48c.ogg","sourceUrl":"","description":"Многих прямо трясёт, когда им пишут «ты тут?», прежде чем вообще объяснить, чего хотят. И если честно, твой ответ на вопрос «Ты тут?» во многом зависит от того, что именно собираются сказать дальше. Если это что-то, чего хочется избежать, в глубине души хочется просто исчезнуть из сети. Забавно всё-таки устроена человеческая психология, да?"},{"id":"ko-Play_Vo_Char_NPC030_vexation_001","title":"Проблемы","language":"Корейский","audioUrl":"/nte-meta/game-audio/b2cc699d88fe16f6de43.ogg","sourceUrl":"","description":"Если меня что и беспокоит, то это, пожалуй, работа. Точнее, даже не сама работа, а отношения в коллективе… Но ты за меня не переживай. Пойми меня правильно, всё это серьёзно, просто… тут, наверное, уже ничего не исправишь, так что и переживать вообще нет смысла."},{"id":"zh-Play_Vo_Char_NPC030_Parry_002","title":"Парирование II","language":"Китайский","audioUrl":"/nte-meta/game-audio/8ff7ce3831d90a663130.ogg","sourceUrl":"","description":"Достойный ответ."},{"id":"zh-Play_Vo_Char_NPC030_weather_003","title":"Холодно","language":"Китайский","audioUrl":"/nte-meta/game-audio/b20e9f8b3d740d56e272.ogg","sourceUrl":"","description":"На, держи. Только что взяла в отделе горячих напитков. Самое то, чтобы согреть руки."},{"id":"en-Play_Vo_Char_NPC030_talk_003","title":"Тема: Контакт","language":"Английский","audioUrl":"/nte-meta/game-audio/127acc2de83442465831.ogg","sourceUrl":"","description":"Любая связь рано или поздно обрывается. День за днём люди принимают эти узы как должное, совершенно забывая о том, что им может прийти конец. Представь, что каждые отношения — это кабель передачи данных, обёрнутый вокруг твоего пальца. Если бы люди могли своими глазами видеть, как он провисает, сворачивается кольцами, пружинит, натягивается струной, истирается, пускает трещины и в конце концов рвётся… неужели они не стали бы охотнее писать то самое лишнее сообщение, делать тот самый лишний звонок и изливать душу тем, кто им по-настоящему дорог?"},{"id":"en-Play_Vo_Char_NPC030_windfall_005","title":"Неожиданная добыча V","language":"Английский","audioUrl":"/nte-meta/game-audio/322a0705aa6fec266d00.ogg","sourceUrl":"","description":"Что для одного мусор, то для другого — сокровище."},{"id":"ja-Play_Vo_Char_NPC030_skill_004","title":"Навык перенаправления IV","language":"Японский","audioUrl":"/nte-meta/game-audio/8bb161fd56143804e3eb.ogg","sourceUrl":"","description":"Ура, сигнал на максимуме!"},{"id":"ko-Play_Vo_Char_NPC030_skill_005","title":"Навык перенаправления V","language":"Корейский","audioUrl":"/nte-meta/game-audio/0adc53d359db98a9ce10.ogg","sourceUrl":"","description":"Пиу-пиу!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_YI_001","title":"Особое переключение — Ския","language":"Корейский","audioUrl":"/nte-meta/game-audio/ad62a6e5027d485d86af.ogg","sourceUrl":"","description":"Ския, не переживай, я возьму это на себя."},{"id":"ko-Play_Vo_Char_NPC030_windfall_006","title":"Неожиданная добыча VI","language":"Корейский","audioUrl":"/nte-meta/game-audio/cd38e6efd3e3973334f3.ogg","sourceUrl":"","description":"Материалы для прокачки? А для какого персонажа?"},{"id":"zh-Play_Vo_Char_NPC030_hstruck_002","title":"Сильный урон II","language":"Китайский","audioUrl":"/nte-meta/game-audio/d7093b2ca32d16687760.ogg","sourceUrl":"","description":"Сильные помехи."},{"id":"en-Play_Vo_Char_NPC030_dead_002","title":"Потеря сознания II","language":"Английский","audioUrl":"/nte-meta/game-audio/58fc9986c76977b99ad9.ogg","sourceUrl":"","description":"Прощай, мир."},{"id":"en-Play_Vo_Char_NPC030_struck_001","title":"Урон I","language":"Английский","audioUrl":"/nte-meta/game-audio/c6b2316d34af3f086896.ogg","sourceUrl":"","description":"Есть попадание."},{"id":"ja-Play_Vo_Char_NPC030_kill_001","title":"Убийство I","language":"Японский","audioUrl":"/nte-meta/game-audio/44cf310c474ac4df73a8.ogg","sourceUrl":"","description":"Я буду помнить тебя."},{"id":"ko-Play_Vo_Char_NPC030_windfall_003","title":"Неожиданная добыча III","language":"Корейский","audioUrl":"/nte-meta/game-audio/20a599f34c936a2ef092.ogg","sourceUrl":"","description":"Тебе это пригодится. Держи!"},{"id":"zh-Play_Vo_Char_NPC030_aoe_UI_001","title":"Сверхспособность I","language":"Китайский","audioUrl":"/nte-meta/game-audio/ca15f25d618620823e50.ogg","sourceUrl":"","description":"Давай сегодня сыграем ещё раз!"},{"id":"en-Play_Vo_Char_NPC030_Fly_002","title":"Планирование II","language":"Английский","audioUrl":"/nte-meta/game-audio/f66e92d215b193cb8ca9.ogg","sourceUrl":"","description":"Сливаюсь с воздухом!"},{"id":"ja-Play_Vo_Char_NPC030_chat_003","title":"Чат: Продолжить общение","language":"Японский","audioUrl":"/nte-meta/game-audio/414d3a5c1c95dbffeeab.ogg","sourceUrl":"","description":"Некоторые люди так боятся неловкого молчания, что вообще не решаются заговорить. Звучит немного парадоксально, но понять их можно. В таких случаях приходится считывать атмосферу, чтобы сообразить, куда повернуть беседу. Безопаснее всего переключиться на что-то банальное вроде погоды или свежих новостей. Хотя и это может выйти боком… Иногда просто не везёт…"},{"id":"ja-Play_Vo_Char_NPC030_QTE_001","title":"Атака на входе I","language":"Японский","audioUrl":"/nte-meta/game-audio/707e01cdaf68b65a5acb.ogg","sourceUrl":"","description":"Бум!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_ZH_001","title":"Особое переключение — Шинку","language":"Японский","audioUrl":"/nte-meta/game-audio/0e0e1a1cf18cbc1f35b2.ogg","sourceUrl":"","description":"Шинку, готова? Сделай глубокий вдох!"},{"id":"ko-Play_Vo_Char_NPC030_hstruck_002","title":"Сильный урон II","language":"Корейский","audioUrl":"/nte-meta/game-audio/e36ee7dbe185c3c6b894.ogg","sourceUrl":"","description":"Сильные помехи."},{"id":"en-Play_Vo_Char_NPC030_containment_002","title":"Сдерживание II","language":"Английский","audioUrl":"/nte-meta/game-audio/9a85c26880cdf6afe5e1.ogg","sourceUrl":"","description":"В компаунде «Целено» можно завести друзей!"},{"id":"en-Play_Vo_Char_NPC030_ug_001","title":"Вознесение персонажа I","language":"Английский","audioUrl":"/nte-meta/game-audio/e9576d9c0e28ee2d7f5f.ogg","sourceUrl":"","description":"Связь стала стабильнее!"},{"id":"ja-Play_Vo_Char_NPC030_self_003","title":"Обо мне: Существование","language":"Японский","audioUrl":"/nte-meta/game-audio/251af061810ddcb21196.ogg","sourceUrl":"","description":"Существую ли я? Ты видишь модель персонажа, интерфейсы, текст, слышишь эту звуковую дорожку и прекрасно понимаешь, что всё это — лишь единицы и нули. Иллюзия, сотканная из цифр и сигналов. Так что, полагаю, для тебя в тот самый миг, когда всё это потеряет смысл, я с тем же успехом могла бы вообще никогда не существовать! А что до смысла, то он должен исходить из «причины» твоего бытия — из вопроса «почему» или «why» — буквы Y. Самое забавное, что с того самого мгновения, как я появилась на свет, у меня уже была моя «Y». И вот ответ на твой вопрос: «Да. Для себя я существую»."}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"ja-Play_Vo_Char_NPC030_talk_002","title":"Тема: Расследования","language":"Японский","audioUrl":"/nte-meta/game-audio/86b62ef49bcd34b6e5d9.ogg","sourceUrl":"","description":"Я могла бы взять пример с Экзе и работать в тёмных уголках сети, где тебя никто не заметит… Но собирать инфу в открытых соцсетях — совсем другое дело. Только я могу без труда разговорить людей и добыть зацепки, которые двигают расследование вперёд. Когда у тебя есть друзья во всех сферах жизни, всё даётся проще. А если мне понадобится друг, я заведу его прямо на месте, ха-ха. Конечно, на людей не всегда можно положиться. Вот тут-то на сцену и выходит Линко. Она считывает важные эмоциональные подсказки. Как только мы фиксируем цель, в дело вступает Хаос. Обычно он выполняет приказы без особых проблем. Если всё пойдёт наперекосяк, я подключаюсь на помощь… Ну, если он, конечно, не забудет позвонить."},{"id":"ko-Play_Vo_Char_NPC030_greet_001","title":"Утреннее приветствие","language":"Корейский","audioUrl":"/nte-meta/game-audio/4a616c463f2e92f008af.ogg","sourceUrl":"","description":"«Доброе утречко», «Утречко», «Проснись и пой!», «Вставай, соня», «Просыпайся»… Между всеми ними столько нюансов. Как же это забавно…"},{"id":"ko-Play_Vo_Char_NPC030_talk_001","title":"Тема: Имя контакта","language":"Корейский","audioUrl":"/nte-meta/game-audio/ed1d5386568945202525.ogg","sourceUrl":"","description":"Имена менять проще простого. Если попросишь, я тебе мигом новое придумаю. Я ж говорю: это примерно то же самое, что поставить ник контакту в соцсетях. К тому же никнейм порой значит куда больше, чем настоящее имя. Хочешь, я дам тебе какое-нибудь особенное прозвище? Как тебе, например, «Какао» или «Прелесть»?"},{"id":"ja-Play_Vo_Char_NPC030_vexation_001","title":"Проблемы","language":"Японский","audioUrl":"/nte-meta/game-audio/18e3303a3c20bec2b8d4.ogg","sourceUrl":"","description":"Если меня что и беспокоит, то это, пожалуй, работа. Точнее, даже не сама работа, а отношения в коллективе… Но ты за меня не переживай. Пойми меня правильно, всё это серьёзно, просто… тут, наверное, уже ничего не исправишь, так что и переживать вообще нет смысла."},{"id":"ko-Play_Vo_Char_NPC030_anomaly_003","title":"Нуллификация I","language":"Корейский","audioUrl":"/nte-meta/game-audio/32ad21ce514f25ff67e1.ogg","sourceUrl":"","description":"Пора тебе возвращаться обратно в море."},{"id":"ko-Play_Vo_Char_NPC030_DodgeCombo_001","title":"Серия критических уклонений I","language":"Корейский","audioUrl":"/nte-meta/game-audio/857f641e9de5c44572e3.ogg","sourceUrl":"","description":"Ю-ху-ху!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_ZERO_001","title":"Особое переключение I — Ноль","language":"Китайский","audioUrl":"/nte-meta/game-audio/ba08327f407375942e58.ogg","sourceUrl":"","description":"Оценщик, мы на одной волне! Оценщица, мы на одной волне!"},{"id":"en-Play_Vo_Char_NPC030_greet_003","title":"Вечернее приветствие","language":"Английский","audioUrl":"/nte-meta/game-audio/28154005a2a5df49a58f.ogg","sourceUrl":"","description":"Заходящее солнце… из-за него всегда кажется, будто пришло время прощаться с другом. От всей этой атмосферы становится так радостно и грустно одновременно."},{"id":"en-Play_Vo_Char_NPC030_hp_003","title":"Низкий уровень здоровья III","language":"Английский","audioUrl":"/nte-meta/game-audio/1467d0e96856be1d556d.ogg","sourceUrl":"","description":"Флуктуации усиливаются…"},{"id":"ja-Play_Vo_Char_NPC030_aoe_UI_003","title":"Сверхспособность III","language":"Японский","audioUrl":"/nte-meta/game-audio/033b2621910ab339fe50.ogg","sourceUrl":"","description":"Открываю сундук, достаю снаряжение!"},{"id":"ja-Play_Vo_Char_NPC030_talk_003","title":"Тема: Контакт","language":"Японский","audioUrl":"/nte-meta/game-audio/c45fada50f95e99ac3cd.ogg","sourceUrl":"","description":"Любая связь рано или поздно обрывается. День за днём люди принимают эти узы как должное, совершенно забывая о том, что им может прийти конец. Представь, что каждые отношения — это кабель передачи данных, обёрнутый вокруг твоего пальца. Если бы люди могли своими глазами видеть, как он провисает, сворачивается кольцами, пружинит, натягивается струной, истирается, пускает трещины и в конце концов рвётся… неужели они не стали бы охотнее писать то самое лишнее сообщение, делать тот самый лишний звонок и изливать душу тем, кто им по-настоящему дорог?"},{"id":"ko-Play_Vo_Char_NPC030_skill_003","title":"Навык перенаправления III","language":"Корейский","audioUrl":"/nte-meta/game-audio/2949be581228aa85ac10.ogg","sourceUrl":"","description":"Запомни этот номер!"},{"id":"zh-Play_Vo_Char_NPC030_about_006","title":"О ТОИ-4","language":"Китайский","audioUrl":"/nte-meta/game-audio/35ae2c2946fa0632461e.ogg","sourceUrl":"","description":"Каждый раз, когда их отряд отправляется на задание, меня так и подмывает улыбнуться — до чего же они сплочённые ребята. В таких местах, как школа или работа, где людей вокруг себя не выбирают, иметь напарников, с которыми ты на одной волне, у которых те же интересы или которые просто понимают тебя с полуслова — о таком можно только мечтать."},{"id":"en-Play_Vo_Char_NPC030_about_005","title":"О ТОИ-6","language":"Английский","audioUrl":"/nte-meta/game-audio/61d7adc6c52e74afa774.ogg","sourceUrl":"","description":"Бюро считает отряд из четырёх человек идеальным составом для подразделений ТОИ. Как только команда достигает этого числа, они больше никого не берут. Хм-м, думаешь, у нас и так тесновато? А Ница на очереди в резерв?.. Это всё потому, что квота не распространяется на напарников-аномалий. Вот Сяочжэнь, например, тоже не считается. Так что в нашем отряде всё ещё свободно одно место."},{"id":"en-Play_Vo_Char_NPC030_dead_003","title":"Потеря сознания III","language":"Английский","audioUrl":"/nte-meta/game-audio/8ae7dc5af94a73332e87.ogg","sourceUrl":"","description":"Всё исказилось… До скорого…"},{"id":"zh-Play_Vo_Char_NPC030_hstruck_001","title":"Сильный урон I","language":"Китайский","audioUrl":"/nte-meta/game-audio/095127bef79a2375e954.ogg","sourceUrl":"","description":"Данные повреждены."},{"id":"en-Play_Vo_Char_NPC030_about_003","title":"О Линко","language":"Английский","audioUrl":"/nte-meta/game-audio/355a9d93ccc788279046.ogg","sourceUrl":"","description":"Линко прямо места себе не находит из-за любых диссонирующих частот. Она всегда из кожи вон лезет, лишь бы мы не ссорились. Она до сих пор не понимает истинных причин, но есть большая вероятность, что со временем она подберётся вплотную к нашим секретам… И что мне делать, когда это случится? Неужели мне взаправду придётся выдать что-то вроде: «Ну и на чьей ты стороне — Экзе или моей?» Уф… какое же лицо она тогда состроит… И если честно, меня до безумия бесит, что я тут единственная, кто ломает над этим голову и составляет планы на экстренный случай."},{"id":"en-Play_Vo_Char_NPC030_skill_005","title":"Навык перенаправления V","language":"Английский","audioUrl":"/nte-meta/game-audio/b5b97a0097cdb3feec41.ogg","sourceUrl":"","description":"Пиу-пиу!"},{"id":"en-Play_Vo_Char_NPC030_SSC_ZH_001","title":"Особое переключение — Шинку","language":"Английский","audioUrl":"/nte-meta/game-audio/64db57f5a6172006e055.ogg","sourceUrl":"","description":"Шинку, готова? Сделай глубокий вдох!"},{"id":"ja-Play_Vo_Char_NPC030_about_004","title":"О Бюро по борьбе с аномалиями","language":"Японский","audioUrl":"/nte-meta/game-audio/dae7036d0a68ba9ac44d.ogg","sourceUrl":"","description":"Бюро заключило со мной соглашение в первую очередь ради того, чтобы сдерживать меня и резко замедлить моё расширение. И лишь во вторую — чтобы использовать мои способности. Я прекрасно это понимаю, уж поверь. Но, несмотря на это, я с самого начала была рада помочь. Посуди самостоятельно: поддержание максимальной стабильности в обществе, от которого я завишу, — это как раз то, что позволяет каждому чувствовать себя в безопасности и копить прекрасные воспоминания с друзьями, верно?"},{"id":"ja-Play_Vo_Char_NPC030_DodgeCombo_001","title":"Серия критических уклонений I","language":"Японский","audioUrl":"/nte-meta/game-audio/a42c4765fabb768f0577.ogg","sourceUrl":"","description":"Ю-ху-ху!"},{"id":"ja-Play_Vo_Char_NPC030_hp_002","title":"Низкий уровень здоровья II","language":"Японский","audioUrl":"/nte-meta/game-audio/ed8d3286b7685ee3b444.ogg","sourceUrl":"","description":"Сигнал слабеет…"},{"id":"ja-Play_Vo_Char_NPC030_talk_001","title":"Тема: Имя контакта","language":"Японский","audioUrl":"/nte-meta/game-audio/74f7d51ec8a1cb16cfd9.ogg","sourceUrl":"","description":"Имена менять проще простого. Если попросишь, я тебе мигом новое придумаю. Я ж говорю: это примерно то же самое, что поставить ник контакту в соцсетях. К тому же никнейм порой значит куда больше, чем настоящее имя. Хочешь, я дам тебе какое-нибудь особенное прозвище? Как тебе, например, «Какао» или «Прелесть»?"},{"id":"ko-Play_Vo_Char_NPC030_DodgeCombo_002","title":"Серия критических уклонений II","language":"Корейский","audioUrl":"/nte-meta/game-audio/c698028317f9d8f0207d.ogg","sourceUrl":"","description":"Просто шажок в сторону."},{"id":"zh-Play_Vo_Char_NPC030_about_003","title":"О Линко","language":"Китайский","audioUrl":"/nte-meta/game-audio/74a47b0552fb545dc0d4.ogg","sourceUrl":"","description":"Линко прямо места себе не находит из-за любых диссонирующих частот. Она всегда из кожи вон лезет, лишь бы мы не ссорились. Она до сих пор не понимает истинных причин, но есть большая вероятность, что со временем она подберётся вплотную к нашим секретам… И что мне делать, когда это случится? Неужели мне взаправду придётся выдать что-то вроде: «Ну и на чьей ты стороне — Экзе или моей?» Уф… какое же лицо она тогда состроит… И если честно, меня до безумия бесит, что я тут единственная, кто ломает над этим голову и составляет планы на экстренный случай."},{"id":"zh-Play_Vo_Char_NPC030_TeammateDown_001","title":"Поражён товарищ по команде – ЭКЗЕ","language":"Китайский","audioUrl":"/nte-meta/game-audio/dc5fdfdcc34050aba8cd.ogg","sourceUrl":"","description":"На сегодня с тебя хватит… До завтра, хорошо?"},{"id":"zh-Play_Vo_Char_NPC030_ug_002","title":"Вознесение персонажа II","language":"Китайский","audioUrl":"/nte-meta/game-audio/8e26aa19d42b8325aa6c.ogg","sourceUrl":"","description":"Моя проекция стала чуть чётче?"},{"id":"ja-Play_Vo_Char_NPC030_Parry_001","title":"Парирование I","language":"Японский","audioUrl":"/nte-meta/game-audio/e1ddd25bdb23d1e6b3a5.ogg","sourceUrl":"","description":"Конечно, давай пожмём руки!"},{"id":"ja-Play_Vo_Char_NPC030_SSC_AHQ_001","title":"Особое переключение — Лакримоза","language":"Японский","audioUrl":"/nte-meta/game-audio/65ae03151a8a23ba9bcc.ogg","sourceUrl":"","description":"Мозочка, можешь ещё немного поспать."},{"id":"ko-Play_Vo_Char_NPC030_TeammateDown_005","title":"Поражен товарищ по команде – Ноль","language":"Корейский","audioUrl":"/nte-meta/game-audio/ec429301cbfc21261b43.ogg","sourceUrl":"","description":"Мой друг в опасности? Так не пойдёт! Моя подруга в опасности? Так не пойдёт!"},{"id":"en-Play_Vo_Char_NPC030_greet_001","title":"Утреннее приветствие","language":"Английский","audioUrl":"/nte-meta/game-audio/49a51484311886639667.ogg","sourceUrl":"","description":"«Доброе утречко», «Утречко», «Проснись и пой!», «Вставай, соня», «Просыпайся»… Между всеми ними столько нюансов. Как же это забавно…"},{"id":"ko-Play_Vo_Char_NPC030_hp_002","title":"Низкий уровень здоровья II","language":"Корейский","audioUrl":"/nte-meta/game-audio/5a9f5f2a29e6c5f6d093.ogg","sourceUrl":"","description":"Сигнал слабеет…"},{"id":"ko-Play_Vo_Char_NPC030_windfall_001","title":"Неожиданная добыча I","language":"Корейский","audioUrl":"/nte-meta/game-audio/ef74b9d31fd3f37287c5.ogg","sourceUrl":"","description":"Может, позвонить кому-нибудь и узнать, кто это потерял?"},{"id":"ko-Play_Vo_Char_NPC030_windfall_005","title":"Неожиданная добыча V","language":"Корейский","audioUrl":"/nte-meta/game-audio/e3be1448422755be63db.ogg","sourceUrl":"","description":"Что для одного мусор, то для другого — сокровище."},{"id":"zh-Play_Vo_Char_NPC030_Parry_001","title":"Парирование I","language":"Китайский","audioUrl":"/nte-meta/game-audio/64b91d3cc4afa05bac09.ogg","sourceUrl":"","description":"Конечно, давай пожмём руки!"},{"id":"zh-Play_Vo_Char_NPC030_skill_001","title":"Навык перенаправления I","language":"Китайский","audioUrl":"/nte-meta/game-audio/38a6d21844d39fbb4171.ogg","sourceUrl":"","description":"Друг, давай установим связь!"},{"id":"ja-Play_Vo_Char_NPC030_weather_003","title":"Холодно","language":"Японский","audioUrl":"/nte-meta/game-audio/3d6c4b4e0cfe84f49391.ogg","sourceUrl":"","description":"На, держи. Только что взяла в отделе горячих напитков. Самое то, чтобы согреть руки."},{"id":"zh-Play_Vo_Char_NPC030_kill_001","title":"Убийство I","language":"Китайский","audioUrl":"/nte-meta/game-audio/1ccaa39d86c5b9664894.ogg","sourceUrl":"","description":"Я буду помнить тебя."},{"id":"en-Play_Vo_Char_NPC030_ug_002","title":"Вознесение персонажа II","language":"Английский","audioUrl":"/nte-meta/game-audio/43afed5b5096818928d5.ogg","sourceUrl":"","description":"Моя проекция стала чуть чётче?"},{"id":"en-Play_Vo_Char_NPC030_weather_002","title":"Дождливо","language":"Английский","audioUrl":"/nte-meta/game-audio/f3e26f6bf19a83ff4829.ogg","sourceUrl":"","description":"А ведь дождевые капли… они ведь как телефонные провода между небом и землёй, правда?"},{"id":"ja-Play_Vo_Char_NPC030_self_001","title":"Обо мне: работа","language":"Японский","audioUrl":"/nte-meta/game-audio/6cc2de2eb60aa17576d3.ogg","sourceUrl":"","description":"Что касается Экзе, я проверяю его отчёты и переписываю всё, что совершенно не похоже на живую человеческую речь. Иногда я даже захожу под его аккаунтом, чтобы говорить от его имени или сглаживать углы в отношениях с другими отделами, которые он умудряется портить в одиночку и абсолютно непреднамеренно. Для Хаоса я синхронизирую разведданные прямо во время операций. А ещё я всегда наготове, чтобы проанализировать ключевые слова в его сообщениях, когда он упоминает какую-нибудь современную вещь, которую явно не знает, как назвать. С Линко я постоянно остаюсь на связи, чтобы подстраховать её в ту же секунду, как она окажется в изоляции. Я звоню ей без предупреждения, чтобы следить, вовремя ли она ложится, рано ли встаёт, идёт ли домой и не засиживается ли с ночи до утра. А ещё я созваниваюсь с её родителями, рассказываю о её успехах и вместе с ними нахваливаю их дочь…"},{"id":"zh-Play_Vo_Char_NPC030_SSC_BH_001","title":"Особое переключение — Минт","language":"Китайский","audioUrl":"/nte-meta/game-audio/436cfe5f917e27e4cc8a.ogg","sourceUrl":"","description":"Эй, Минт, у меня для тебя сюрприз — небольшая викторина!"},{"id":"en-Play_Vo_Char_NPC030_gift_003","title":"Подарок получен III","language":"Английский","audioUrl":"/nte-meta/game-audio/62e83b6a18e83cf6fc22.ogg","sourceUrl":"","description":"Ого, это что, маленький дружеский сюрприз?"},{"id":"en-Play_Vo_Char_NPC030_TeammateDown_003","title":"Поражён товарищ по команде – Линко","language":"Английский","audioUrl":"/nte-meta/game-audio/8cca37ad7f057b94bcf5.ogg","sourceUrl":"","description":"Всё в порядке. Наша связь не прервалась."},{"id":"ja-Play_Vo_Char_NPC030_about_003","title":"О Линко","language":"Японский","audioUrl":"/nte-meta/game-audio/618672b88bfe9eb98ff9.ogg","sourceUrl":"","description":"Линко прямо места себе не находит из-за любых диссонирующих частот. Она всегда из кожи вон лезет, лишь бы мы не ссорились. Она до сих пор не понимает истинных причин, но есть большая вероятность, что со временем она подберётся вплотную к нашим секретам… И что мне делать, когда это случится? Неужели мне взаправду придётся выдать что-то вроде: «Ну и на чьей ты стороне — Экзе или моей?» Уф… какое же лицо она тогда состроит… И если честно, меня до безумия бесит, что я тут единственная, кто ломает над этим голову и составляет планы на экстренный случай."},{"id":"ja-Play_Vo_Char_NPC030_skill_002","title":"Навык перенаправления II","language":"Японский","audioUrl":"/nte-meta/game-audio/d99443a77aab962157a0.ogg","sourceUrl":"","description":"Я тебе позвонила. Перезвони мне!"},{"id":"zh-Play_Vo_Char_NPC030_chat_003","title":"Чат: Продолжить общение","language":"Китайский","audioUrl":"/nte-meta/game-audio/37f9b8912e86f82a6237.ogg","sourceUrl":"","description":"Некоторые люди так боятся неловкого молчания, что вообще не решаются заговорить. Звучит немного парадоксально, но понять их можно. В таких случаях приходится считывать атмосферу, чтобы сообразить, куда повернуть беседу. Безопаснее всего переключиться на что-то банальное вроде погоды или свежих новостей. Хотя и это может выйти боком… Иногда просто не везёт…"},{"id":"zh-Play_Vo_Char_NPC030_gift_001","title":"Подарок получен I","language":"Китайский","audioUrl":"/nte-meta/game-audio/92e9d94ffa833485b64a.ogg","sourceUrl":"","description":"Какой классный подарок! Надо бы найти ему местечко…"},{"id":"ko-Play_Vo_Char_NPC030_aoe_UI_003","title":"Сверхспособность III","language":"Корейский","audioUrl":"/nte-meta/game-audio/85cf843ba7276e7b1221.ogg","sourceUrl":"","description":"Открываю сундук, достаю снаряжение!"},{"id":"ko-Play_Vo_Char_NPC030_Parry_001","title":"Парирование I","language":"Корейский","audioUrl":"/nte-meta/game-audio/d89adf57d8d503e671ab.ogg","sourceUrl":"","description":"Конечно, давай пожмём руки!"},{"id":"zh-Play_Vo_Char_NPC030_anomaly_003","title":"Нуллификация I","language":"Китайский","audioUrl":"/nte-meta/game-audio/26a3b21134584ff1c3a7.ogg","sourceUrl":"","description":"Пора тебе возвращаться обратно в море."},{"id":"zh-Play_Vo_Char_NPC030_DodgeCombo_002","title":"Серия критических уклонений II","language":"Китайский","audioUrl":"/nte-meta/game-audio/3b8f6b4efa20c6c73c73.ogg","sourceUrl":"","description":"Просто шажок в сторону."},{"id":"en-Play_Vo_Char_NPC030_TeammateDown_002","title":"Поражён товарищ по команде — Хаос","language":"Английский","audioUrl":"/nte-meta/game-audio/04d86c611b7df4c37789.ogg","sourceUrl":"","description":"Не время для последних слов. Это ещё не конец!"},{"id":"ja-Play_Vo_Char_NPC030_hstruck_001","title":"Сильный урон I","language":"Японский","audioUrl":"/nte-meta/game-audio/f9b3d56d7ee0cbbf5c58.ogg","sourceUrl":"","description":"Данные повреждены."},{"id":"ja-Play_Vo_Char_NPC030_SSC_YLY_001","title":"Особое переключение: Ирой","language":"Японский","audioUrl":"/nte-meta/game-audio/88c5b44dd79042be3796.ogg","sourceUrl":"","description":"Передай привет ребяткам в своих снах!"},{"id":"ja-Play_Vo_Char_NPC030_ug_003","title":"Вознесение персонажа III","language":"Японский","audioUrl":"/nte-meta/game-audio/c8aab7058dde08bb4501.ogg","sourceUrl":"","description":"Такое чувство, будто я могу дозвониться в мгновение ока, даже туда, где вообще не ловит сеть."},{"id":"ko-Play_Vo_Char_NPC030_weather_002","title":"Дождливо","language":"Корейский","audioUrl":"/nte-meta/game-audio/400329ee8d5944e7ad0b.ogg","sourceUrl":"","description":"А ведь дождевые капли… они ведь как телефонные провода между небом и землёй, правда?"},{"id":"en-Play_Vo_Char_NPC030_SSC_ZERO_002","title":"Особое переключение II — Ноль","language":"Английский","audioUrl":"/nte-meta/game-audio/ed6200ea9f93c535c512.ogg","sourceUrl":"","description":"Ладно, теперь моя очередь тебе помочь!"},{"id":"ja-Play_Vo_Char_NPC030_deploy_001","title":"Отправка I","language":"Японский","audioUrl":"/nte-meta/game-audio/117547baa4b54303efaa.ogg","sourceUrl":"","description":"Позвони мне — и я сразу буду рядом!"},{"id":"ja-Play_Vo_Char_NPC030_hp_003","title":"Низкий уровень здоровья III","language":"Японский","audioUrl":"/nte-meta/game-audio/84a21d583ce15d390613.ogg","sourceUrl":"","description":"Флуктуации усиливаются…"},{"id":"ja-Play_Vo_Char_NPC030_TeammateDown_005","title":"Поражен товарищ по команде – Ноль","language":"Японский","audioUrl":"/nte-meta/game-audio/04fbf9c941fba26617c6.ogg","sourceUrl":"","description":"Мой друг в опасности? Так не пойдёт! Моя подруга в опасности? Так не пойдёт!"},{"id":"ko-Play_Vo_Char_NPC030_dead_001","title":"Потеря сознания I","language":"Корейский","audioUrl":"/nte-meta/game-audio/6d0f01ca67513f4af89b.ogg","sourceUrl":"","description":"Связь обрывается…"},{"id":"ko-Play_Vo_Char_NPC030_Switch_003","title":"Переключение III","language":"Корейский","audioUrl":"/nte-meta/game-audio/fa9a009d95601d2dfffd.ogg","sourceUrl":"","description":"С проекцией всё стабильно?"},{"id":"ko-Play_Vo_Char_NPC030_weather_001","title":"Солнечно","language":"Корейский","audioUrl":"/nte-meta/game-audio/44a64045144210c5baef.ogg","sourceUrl":"","description":"В такую отличную погоду просто грех сидеть дома — надо выбраться куда-нибудь и забить день планами до отказа, верно?"},{"id":"zh-Play_Vo_Char_NPC030_greet_001","title":"Утреннее приветствие","language":"Китайский","audioUrl":"/nte-meta/game-audio/fb7c245b29a128ca9756.ogg","sourceUrl":"","description":"«Доброе утречко», «Утречко», «Проснись и пой!», «Вставай, соня», «Просыпайся»… Между всеми ними столько нюансов. Как же это забавно…"},{"id":"en-Play_Vo_Char_NPC030_QTE_001","title":"Атака на входе I","language":"Английский","audioUrl":"/nte-meta/game-audio/979a9bc092bdcec99251.ogg","sourceUrl":"","description":"Бум!"},{"id":"en-Play_Vo_Char_NPC030_ug_003","title":"Вознесение персонажа III","language":"Английский","audioUrl":"/nte-meta/game-audio/b7db81112793cbb474e8.ogg","sourceUrl":"","description":"Такое чувство, будто я могу дозвониться в мгновение ока, даже туда, где вообще не ловит сеть."},{"id":"ja-Play_Vo_Char_NPC030_fh_001","title":"Исцеление I","language":"Японский","audioUrl":"/nte-meta/game-audio/e735c1e8d3f0786c1990.ogg","sourceUrl":"","description":"Связь восстановилась!"},{"id":"ko-Play_Vo_Char_NPC030_greet_004","title":"Спокойной ночи","language":"Корейский","audioUrl":"/nte-meta/game-audio/ce7ad5aa3576ec66aa82.ogg","sourceUrl":"","description":"Отдых необходим человеческому телу. Но стоит тебе заснуть, как разум теряет бдительность, и всё, что было похоронено в подсознании, всплывает наружу. Так что по-настоящему расслабиться всё равно не получается. Тяжело это."},{"id":"ko-Play_Vo_Char_NPC030_hobby_001","title":"Хобби","language":"Корейский","audioUrl":"/nte-meta/game-audio/00c4f02971f7c0d5c83c.ogg","sourceUrl":"","description":"Болтать с друзьями часами по телефону, переписываться по почте, слать голосовые, созваниваться по видео или просто строчить сообщения… У каждого из этих способов свой неповторимый вайб, и я обожаю абсолютно все варианты оставаться на связи! А вообще, у меня ещё куча самых разных увлечений… Ой, ну и видеоигры я просто обожаю!"},{"id":"ko-Play_Vo_Char_NPC030_skill_001","title":"Навык перенаправления I","language":"Корейский","audioUrl":"/nte-meta/game-audio/e2d2a3cdb5233a7950c4.ogg","sourceUrl":"","description":"Друг, давай установим связь!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_ZERO_001","title":"Особое переключение I — Ноль","language":"Корейский","audioUrl":"/nte-meta/game-audio/0f1e949ca7607d21fa95.ogg","sourceUrl":"","description":"Оценщик, мы на одной волне! Оценщица, мы на одной волне!"},{"id":"zh-Play_Vo_Char_NPC030_deploy_002","title":"Отправка II","language":"Китайский","audioUrl":"/nte-meta/game-audio/ce10f4594b3ff9fee97a.ogg","sourceUrl":"","description":"Привет, старые и новые друзья!"},{"id":"zh-Play_Vo_Char_NPC030_SSC_YI_001","title":"Особое переключение — Ския","language":"Китайский","audioUrl":"/nte-meta/game-audio/8a0a1499b72245630af6.ogg","sourceUrl":"","description":"Ския, не переживай, я возьму это на себя."},{"id":"en-Play_Vo_Char_NPC030_windfall_004","title":"Неожиданная добыча IV","language":"Английский","audioUrl":"/nte-meta/game-audio/b83de05e11c5d47217e1.ogg","sourceUrl":"","description":"Ему будет одиноко, если его никто не подберёт."},{"id":"ja-Play_Vo_Char_NPC030_SSC_ZERO_002","title":"Особое переключение II — Ноль","language":"Японский","audioUrl":"/nte-meta/game-audio/a9bac2407cdf8d4ba696.ogg","sourceUrl":"","description":"Ладно, теперь моя очередь тебе помочь!"},{"id":"ko-Play_Vo_Char_NPC030_anomaly_004","title":"Нуллификация II","language":"Корейский","audioUrl":"/nte-meta/game-audio/dea0cf536105508bda65.ogg","sourceUrl":"","description":"Рада была познакомиться! Ещё увидимся!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_EXE_001","title":"Особое переключение I — Экзе","language":"Корейский","audioUrl":"/nte-meta/game-audio/2cca8963731c59ef3809.ogg","sourceUrl":"","description":"Ого, Экзе, ты всё-таки вышел из своей комнаты!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_EXE_002","title":"Особое переключение II — Экзе","language":"Корейский","audioUrl":"/nte-meta/game-audio/d28fd4c83e03bd7ffbfc.ogg","sourceUrl":"","description":"Это тебе самому пора ползти обратно в бэкенд!"},{"id":"zh-Play_Vo_Char_NPC030_gift_004","title":"Подарок получен IV","language":"Китайский","audioUrl":"/nte-meta/game-audio/6d43b64bbe011a8b46f9.ogg","sourceUrl":"","description":"Спасибо! Так, теперь мне надо придумать, что подарить тебе в ответ! Хм-м…"},{"id":"zh-Play_Vo_Char_NPC030_talk_003","title":"Тема: Контакт","language":"Китайский","audioUrl":"/nte-meta/game-audio/126229e81de2f0471364.ogg","sourceUrl":"","description":"Любая связь рано или поздно обрывается. День за днём люди принимают эти узы как должное, совершенно забывая о том, что им может прийти конец. Представь, что каждые отношения — это кабель передачи данных, обёрнутый вокруг твоего пальца. Если бы люди могли своими глазами видеть, как он провисает, сворачивается кольцами, пружинит, натягивается струной, истирается, пускает трещины и в конце концов рвётся… неужели они не стали бы охотнее писать то самое лишнее сообщение, делать тот самый лишний звонок и изливать душу тем, кто им по-настоящему дорог?"},{"id":"zh-Play_Vo_Char_NPC030_ug_001","title":"Вознесение персонажа I","language":"Китайский","audioUrl":"/nte-meta/game-audio/4f2a3007236ed172b680.ogg","sourceUrl":"","description":"Связь стала стабильнее!"},{"id":"en-Play_Vo_Char_NPC030_kill_002","title":"Убийство II","language":"Английский","audioUrl":"/nte-meta/game-audio/6877e4cefbcbed8855fb.ogg","sourceUrl":"","description":"Ты ещё вернёшься!"},{"id":"en-Play_Vo_Char_NPC030_talk_002","title":"Тема: Расследования","language":"Английский","audioUrl":"/nte-meta/game-audio/e897661408e72637879d.ogg","sourceUrl":"","description":"Я могла бы взять пример с Экзе и работать в тёмных уголках сети, где тебя никто не заметит… Но собирать инфу в открытых соцсетях — совсем другое дело. Только я могу без труда разговорить людей и добыть зацепки, которые двигают расследование вперёд. Когда у тебя есть друзья во всех сферах жизни, всё даётся проще. А если мне понадобится друг, я заведу его прямо на месте, ха-ха. Конечно, на людей не всегда можно положиться. Вот тут-то на сцену и выходит Линко. Она считывает важные эмоциональные подсказки. Как только мы фиксируем цель, в дело вступает Хаос. Обычно он выполняет приказы без особых проблем. Если всё пойдёт наперекосяк, я подключаюсь на помощь… Ну, если он, конечно, не забудет позвонить."},{"id":"ko-Play_Vo_Char_NPC030_fh_002","title":"Исцеление II","language":"Корейский","audioUrl":"/nte-meta/game-audio/2633f230d53e1e24c15c.ogg","sourceUrl":"","description":"Системы восстанавливаются."},{"id":"en-Play_Vo_Char_NPC030_about_004","title":"О Бюро по борьбе с аномалиями","language":"Английский","audioUrl":"/nte-meta/game-audio/2cd2d08e369d69ca26a9.ogg","sourceUrl":"","description":"Бюро заключило со мной соглашение в первую очередь ради того, чтобы сдерживать меня и резко замедлить моё расширение. И лишь во вторую — чтобы использовать мои способности. Я прекрасно это понимаю, уж поверь. Но, несмотря на это, я с самого начала была рада помочь. Посуди самостоятельно: поддержание максимальной стабильности в обществе, от которого я завишу, — это как раз то, что позволяет каждому чувствовать себя в безопасности и копить прекрасные воспоминания с друзьями, верно?"},{"id":"en-Play_Vo_Char_NPC030_gift_004","title":"Подарок получен IV","language":"Английский","audioUrl":"/nte-meta/game-audio/4bd9f7faf698eb9f975b.ogg","sourceUrl":"","description":"Спасибо! Так, теперь мне надо придумать, что подарить тебе в ответ! Хм-м…"},{"id":"ja-Play_Vo_Char_NPC030_TeammateDown_002","title":"Поражён товарищ по команде — Хаос","language":"Японский","audioUrl":"/nte-meta/game-audio/2fb89a1cc234a44e17f4.ogg","sourceUrl":"","description":"Не время для последних слов. Это ещё не конец!"},{"id":"ko-Play_Vo_Char_NPC030_aoe_UI_002","title":"Сверхспособность II","language":"Корейский","audioUrl":"/nte-meta/game-audio/a62d1066b5b06fcfce45.ogg","sourceUrl":"","description":"Пора играть! Погнали!"},{"id":"zh-Play_Vo_Char_NPC030_anomaly_004","title":"Нуллификация II","language":"Китайский","audioUrl":"/nte-meta/game-audio/eb3c7f816b9397cbe78c.ogg","sourceUrl":"","description":"Рада была познакомиться! Ещё увидимся!"},{"id":"ja-Play_Vo_Char_NPC030_Fly_002","title":"Планирование II","language":"Японский","audioUrl":"/nte-meta/game-audio/3d8fdfbb71a67c45ee71.ogg","sourceUrl":"","description":"Сливаюсь с воздухом!"},{"id":"ja-Play_Vo_Char_NPC030_gift_001","title":"Подарок получен I","language":"Японский","audioUrl":"/nte-meta/game-audio/644f3c48ad2cebd7430c.ogg","sourceUrl":"","description":"Какой классный подарок! Надо бы найти ему местечко…"},{"id":"ja-Play_Vo_Char_NPC030_ug_001","title":"Вознесение персонажа I","language":"Японский","audioUrl":"/nte-meta/game-audio/c0738a1d75d925510f61.ogg","sourceUrl":"","description":"Связь стала стабильнее!"},{"id":"ko-Play_Vo_Char_NPC030_greet_002","title":"Дневное приветствие","language":"Корейский","audioUrl":"/nte-meta/game-audio/de38791b8419b0744f49.ogg","sourceUrl":"","description":"Сны во время полуденного отдыха обычно приятнее, чем ночные. Это потому, что они в буквальном смысле «дневные грёзы»?"},{"id":"ja-Play_Vo_Char_NPC030_aoe_UI_001","title":"Сверхспособность I","language":"Японский","audioUrl":"/nte-meta/game-audio/66dba922ab6d486e4273.ogg","sourceUrl":"","description":"Давай сегодня сыграем ещё раз!"},{"id":"ja-Play_Vo_Char_NPC030_dead_001","title":"Потеря сознания I","language":"Японский","audioUrl":"/nte-meta/game-audio/d658b5c912d2af6086f8.ogg","sourceUrl":"","description":"Связь обрывается…"},{"id":"ja-Play_Vo_Char_NPC030_skill_003","title":"Навык перенаправления III","language":"Японский","audioUrl":"/nte-meta/game-audio/fedcfcd07dd0d3fadbaa.ogg","sourceUrl":"","description":"Запомни этот номер!"},{"id":"ko-Play_Vo_Char_NPC030_self_001","title":"Обо мне: работа","language":"Корейский","audioUrl":"/nte-meta/game-audio/f8a803c220ec71688b41.ogg","sourceUrl":"","description":"Что касается Экзе, я проверяю его отчёты и переписываю всё, что совершенно не похоже на живую человеческую речь. Иногда я даже захожу под его аккаунтом, чтобы говорить от его имени или сглаживать углы в отношениях с другими отделами, которые он умудряется портить в одиночку и абсолютно непреднамеренно. Для Хаоса я синхронизирую разведданные прямо во время операций. А ещё я всегда наготове, чтобы проанализировать ключевые слова в его сообщениях, когда он упоминает какую-нибудь современную вещь, которую явно не знает, как назвать. С Линко я постоянно остаюсь на связи, чтобы подстраховать её в ту же секунду, как она окажется в изоляции. Я звоню ей без предупреждения, чтобы следить, вовремя ли она ложится, рано ли встаёт, идёт ли домой и не засиживается ли с ночи до утра. А ещё я созваниваюсь с её родителями, рассказываю о её успехах и вместе с ними нахваливаю их дочь…"},{"id":"zh-Play_Vo_Char_NPC030_Switch_003","title":"Переключение III","language":"Китайский","audioUrl":"/nte-meta/game-audio/cb25a1ff482ed6ea710b.ogg","sourceUrl":"","description":"С проекцией всё стабильно?"},{"id":"zh-Play_Vo_Char_NPC030_TeammateDown_003","title":"Поражён товарищ по команде – Линко","language":"Китайский","audioUrl":"/nte-meta/game-audio/9137cc9760317283d296.ogg","sourceUrl":"","description":"Всё в порядке. Наша связь не прервалась."},{"id":"ja-Play_Vo_Char_NPC030_hp_001","title":"Низкий уровень здоровья I","language":"Японский","audioUrl":"/nte-meta/game-audio/9d2145cbba77685ce3e0.ogg","sourceUrl":"","description":"Связь становится нестабильной…"},{"id":"ja-Play_Vo_Char_NPC030_windfall_006","title":"Неожиданная добыча VI","language":"Японский","audioUrl":"/nte-meta/game-audio/6bf1b570a57322788dcf.ogg","sourceUrl":"","description":"Материалы для прокачки? А для какого персонажа?"},{"id":"ko-Play_Vo_Char_NPC030_dead_002","title":"Потеря сознания II","language":"Корейский","audioUrl":"/nte-meta/game-audio/db6a33f03f63fd8414c1.ogg","sourceUrl":"","description":"Прощай, мир."},{"id":"ko-Play_Vo_Char_NPC030_SSC_KES_001","title":"Особое переключение I — Хаос","language":"Корейский","audioUrl":"/nte-meta/game-audio/7838dea2c7dd573651f5.ogg","sourceUrl":"","description":"Хаос, я прикрою!"},{"id":"ko-Play_Vo_Char_NPC030_SSC_LK_001","title":"Особое переключение I — Линко","language":"Корейский","audioUrl":"/nte-meta/game-audio/0a4403443103823bffe7.ogg","sourceUrl":"","description":"Линко, подключайся и меняемся!"},{"id":"ko-Play_Vo_Char_NPC030_Switch_002","title":"Переключение II","language":"Корейский","audioUrl":"/nte-meta/game-audio/24c085896759a9b1c3bd.ogg","sourceUrl":"","description":"Подключилась — и я уже здесь!"},{"id":"zh-Play_Vo_Char_NPC030_talk_001","title":"Тема: Имя контакта","language":"Китайский","audioUrl":"/nte-meta/game-audio/66e3d52dd104219e1300.ogg","sourceUrl":"","description":"Имена менять проще простого. Если попросишь, я тебе мигом новое придумаю. Я ж говорю: это примерно то же самое, что поставить ник контакту в соцсетях. К тому же никнейм порой значит куда больше, чем настоящее имя. Хочешь, я дам тебе какое-нибудь особенное прозвище? Как тебе, например, «Какао» или «Прелесть»?"},{"id":"en-Play_Vo_Char_NPC030_DodgeCombo_002","title":"Серия критических уклонений II","language":"Английский","audioUrl":"/nte-meta/game-audio/b215327bbb6f3566e89c.ogg","sourceUrl":"","description":"Просто шажок в сторону."},{"id":"en-Play_Vo_Char_NPC030_fh_002","title":"Исцеление II","language":"Английский","audioUrl":"/nte-meta/game-audio/11e6034814bbc5b3c008.ogg","sourceUrl":"","description":"Системы восстанавливаются."},{"id":"en-Play_Vo_Char_NPC030_SSC_EXE_002","title":"Особое переключение II — Экзе","language":"Английский","audioUrl":"/nte-meta/game-audio/f8c920c97ce3464d2be8.ogg","sourceUrl":"","description":"Это тебе самому пора ползти обратно в бэкенд!"},{"id":"ko-Play_Vo_Char_NPC030_kill_001","title":"Убийство I","language":"Корейский","audioUrl":"/nte-meta/game-audio/b740cb5ece139ae9d57c.ogg","sourceUrl":"","description":"Я буду помнить тебя."},{"id":"ko-Play_Vo_Char_NPC030_kill_002","title":"Убийство II","language":"Корейский","audioUrl":"/nte-meta/game-audio/bab6491926dae1a58f4f.ogg","sourceUrl":"","description":"Ты ещё вернёшься!"}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

UPDATE character_profiles SET awakenings_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(awakenings_json) UNION ALL SELECT value FROM json_each('[{"level":1,"kind":"awakening","name":"404: Остров недоступен","iconUrl":"/nte-meta/game-assets/5182a73a025f945934e6.webp","description":"Увеличивает крит. урон всей команды на 10 % на 20 сек. за каждый 1 заряд Оптической иллюзии, израсходованный перед применением «У тебя бывает дежавю?». При повторном срабатывании сбрасывает накопленное количество израсходованных зарядов Оптической иллюзии и обновляет эффект и длительность усиления."},{"level":2,"kind":"awakening","name":"200: Узлы соединены","iconUrl":"/nte-meta/game-assets/2ca1376e6ae47ffbccd8.webp","description":"Увеличивает множитель урона навыка «У тебя бывает дежавю?» на 30 %.\n\nПри применении навыка «Прощание с тобой» его урон игнорирует 5 % защиты цели за каждый 1 израсходованный заряд Оптической иллюзии."},{"level":3,"kind":"awakening","name":"504: Время ожидания ответа от шлюза истекло","iconUrl":"/nte-meta/game-assets/098f244fb0571d76bdb8.webp","description":"Даёт 3 уровня Оптической иллюзии, когда Мощность сигнала повышается со Среднего уровня сигнала до Высокого уровня сигнала.\n\nОптическая иллюзия складывается до 4 раз."},{"level":4,"kind":"awakening","name":"302: Желание перенаправлено","iconUrl":"/nte-meta/game-assets/e46438ded6f0933eecb1.webp","description":"Увеличивает крит. урон всей команды на 20 %, пока Элимс находится в команде и жива."},{"level":5,"kind":"awakening","name":"304: Без изменений","iconUrl":"/nte-meta/game-assets/b0293b187dddc4488d07.webp","description":"Увеличивает множитель урона навыка «Те, кто ушёл» на 100 %.\n\nПри вступлении в бой энергия цикла Элимс устанавливается на 100. Перезарядка: 30 сек. Срабатывает не более одного раза за бой."},{"level":6,"kind":"awakening","name":"301: Перемещено навсегда","iconUrl":"/nte-meta/game-assets/64c03c0bbc916f4647d7.webp","description":"Увеличивает урон последующих атак Элимс на 25 % на 20 сек. за каждый 1 заряд Оптической иллюзии, израсходованный до применения «У тебя бывает дежавю?». При повторном срабатывании сбрасывает накопленное количество израсходованных зарядов Оптической иллюзии и обновляет эффект и длительность усиления."},{"level":3,"kind":"resonance","name":"За былые времена, мой друг","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Повышает уровень базовой атаки, навыка перенаправления и сверхспособности Элимс на 1. После применения «Я здесь» или «Прерывистое существование» при Низком уровне сигнала повышает Мощность сигнала сразу до Высокого уровня сигнала.\n\nАктивирует эффекты перехода от Низкого уровня сигнала к Среднему уровню сигнала, а затем — эффекты перехода от Среднего уровня сигнала к Высокому уровню сигнала. Позволяет Элимс немедленно применить «Прощание с тобой», когда Мощность сигнала повышается до Высокого уровня сигнала."},{"level":6,"kind":"resonance","name":"До встречи, новый друг","iconUrl":"/nte-meta/game-assets/8973f2ebfb1fbdaed6e8.webp","description":"Урон всех участников отряда игнорирует 12 % всех видов сопротивления цели, пока Элимс жива и находится в отряде.\n\nНаносит 1 дополнительный удар с уроном космоса, когда последний удар навыка «Прощание с тобой» попадает по цели, если навык израсходовал Оптическую иллюзию. На текущем уровне навыка «Подсчёт электрических овец» множитель урона этого дополнительного удара составляет 168 % за каждый израсходованный заряд Оптической иллюзии."}]'))) WHERE character_id IN (SELECT id FROM nte_release_0056);

UPDATE character_profiles
SET skins_json=(SELECT json_group_array(json(CASE WHEN json_extract(value,'$.id')='skin-10jszw9'
  AND json_extract(value,'$.imageUrl')='https://interactivemap.app/neverness-to-everness/database/assets/illustrations/YH_UI_shizhuang_big_zhenhong5.png' THEN json_set(value,'$.imageUrl','/nte-meta/game-assets/4529a0f832bcfdf3d24c.webp') ELSE value END)) FROM json_each(skins_json))
WHERE character_id=(SELECT id FROM characters WHERE slug='shinku')
  AND EXISTS(SELECT 1 FROM json_each(skins_json) WHERE json_extract(value,'$.id')='skin-10jszw9' AND json_extract(value,'$.imageUrl')='https://interactivemap.app/neverness-to-everness/database/assets/illustrations/YH_UI_shizhuang_big_zhenhong5.png');

CREATE TABLE nte_guide_0056 (id TEXT PRIMARY KEY);

INSERT INTO nte_guide_0056 SELECT 'guide-elyms-0056' FROM nte_release_0056 WHERE NOT EXISTS(SELECT 1 FROM guides WHERE id='guide-elyms-0056' OR slug='elyms-build-guide' OR (character_id='elyms' AND status='published'));

INSERT INTO guides(id,slug,character_id,title,summary,status,patch_version) SELECT 'guide-elyms-0056', 'elyms-build-guide', 'elyms', 'Элимс: сигнал, сборка и ротация', 'Как поднять сигнал, усилить отряд и выбрать твёрдую дугу.', 'published', '1.5' FROM nte_guide_0056;

INSERT INTO guide_sections(id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'guide-elyms-0056-overview', 'guide-elyms-0056', 'Как играть', 'overview', 'Элимс — поддержка космоса с уроном вне поля. Сверхспособность даёт отряду атаку от её базовой атаки и усиливает последующие атаки. Урон сверхспособности и «Воспоминания» зависит от уровня сигнала в момент применения.', '1', '{}' FROM nte_guide_0056;

INSERT INTO guide_sections(id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'guide-elyms-0056-skill-priority', 'guide-elyms-0056', 'Приоритет прокачки навыков', 'skill-priority', 'Сначала сверхспособность: от неё зависят командные усиления и «Воспоминание». Затем перенаправление и базовые атаки для личного урона.', '2', '{"visual":{"kind":"skills","items":[{"id":"GA_Elyms_UltraSkill","name":"У тебя бывает дежавю?","skillType":"Сверхспособность","imageUrl":"/nte-meta/game-assets/19788fa0f9e79a2dfa9d.webp","description":"","stats":[]},{"id":"GA_Elyms_Skill","name":"Подсчёт электрических овец","skillType":"Навык перенаправления","imageUrl":"/nte-meta/game-assets/b663411e5875b92723be.webp","description":"","stats":[]},{"id":"GA_Elyms_Melee","name":"Мгновенный сбой","skillType":"Базовая атака","imageUrl":"/nte-meta/game-assets/fea48236d01734f70863.webp","description":"","stats":[]},{"id":"GA_Elyms_QTE","name":"Я здесь","skillType":"Навык поддержки","imageUrl":"/nte-meta/game-assets/5caf31608d5c1f4b3dac.webp","description":"","stats":[]}]}}' FROM nte_guide_0056;

INSERT INTO guide_sections(id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'guide-elyms-0056-best-arcs', 'guide-elyms-0056', 'Лучшие дуги', 'best-arcs', 'Эхо в режиме ожидания усиливает команду. Альтернативы выбирайте по тому, нужен ли отряду бонус атаки или личный урон Элимс.', '3', '{"visual":{"kind":"arcs","items":[{"id":"fork_elyms","name":"Эхо в режиме ожидания","imageUrl":"/nte-meta/game-assets/256d46a0aab99625e3ad.webp","description":"Командное игнорирование защиты и пробитие сопротивления космосу.","category":"signature","stats":[{"label":"Атака · ур. 80","value":"570"},{"label":"Шанс крит. удара · ур. 80","value":"24%"}]},{"id":"fork_bitgame","name":"Взорвать толпу","imageUrl":"/nte-meta/game-assets/87ee738f0d9c7e6937d6.webp","description":"Бонус атаки активному герою, пока Элимс вне поля.","category":"replacement","stats":[{"label":"Атака · ур. 80","value":"512"},{"label":"Атака · ур. 80","value":"27.5%"}]},{"id":"fork_worldrain","name":"Дождь, сотрясший мир","imageUrl":"/nte-meta/game-assets/4011a90ad0a6ba91fabe.webp","description":"Усиливает её перенаправление и сверхспособность.","category":"replacement","stats":[{"label":"Атака · ур. 80","value":"512"},{"label":"Шанс крит. удара · ур. 80","value":"22%"}]},{"id":"fork_nonos","name":"Первый шаг к успеху","imageUrl":"/nte-meta/game-assets/b6577207e900f36fef5b.webp","description":"Бонус личной атаки после перенаправления.","category":"budget","stats":[{"label":"Атака · ур. 80","value":"380"},{"label":"Атака · ур. 80","value":"20%"}]}]}}' FROM nte_guide_0056;

INSERT INTO guide_sections(id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'guide-elyms-0056-cartridges', 'guide-elyms-0056', 'Лучшие картриджи', 'cartridges', 'Для личного урона космоса подойдёт «Утраченное сияние». «Кредо теней» — вариант через атаку, если уже собран хороший комплект.', '4', '{"visual":{"kind":"cartridges","items":[{"id":"suit6","name":"Утраченное сияние","imageUrl":"/nte-meta/game-assets/96dd14147e5aa46bb31f.webp","description":"Бонус урона космоса и игнорирование защиты после сверхспособности.","category":"signature","stats":[{"label":"2 предмета","value":"Эпический (2): урон космоса +10 %."},{"label":"4 предмета","value":"Легендарный (4): после применения владельцем сверхспособности игнорирует 25 % защиты врагов в течение 20 сек. Эффект не складывается."}]},{"id":"suit8","name":"Кредо теней","imageUrl":"/nte-meta/game-assets/8bb946a29a8a29e677e8.webp","description":"Личная атака после навыка.","category":"replacement","stats":[{"label":"2 предмета","value":"Эпический (2): атака +10 %."},{"label":"4 предмета","value":"Легендарный (4): после применения навыка увеличивает атаку носителя на 25 % на 20 сек."}]}]}}' FROM nte_guide_0056;

INSERT INTO guide_sections(id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'guide-elyms-0056-main-stats', 'guide-elyms-0056', 'Основные статы', 'main-stats', 'Для личного урона подбирайте критические характеристики, атаку и урон космоса. Бонус атаки отряду считается от базовой атаки; не оценивайте его только по процентам на картриджах.', '5', '{"visual":{"kind":"stats","items":[{"id":"stat-1","name":"Шанс крит. удара","description":"","imageUrl":"/nte-meta/game-assets/ad87d2a73478180243f0.webp","stats":[]},{"id":"stat-2","name":"Крит. урон","description":"","imageUrl":"/nte-meta/game-assets/56f87c7e7402bf44ff21.webp","stats":[]},{"id":"stat-3","name":"Атака %","description":"","imageUrl":"/nte-meta/game-assets/ba0908d08ebf5aa48c91.webp","stats":[]},{"id":"stat-4","name":"Урон космоса","description":"","imageUrl":"","stats":[]}]}}' FROM nte_guide_0056;

INSERT INTO guide_sections(id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'guide-elyms-0056-rotations', 'guide-elyms-0056', 'Базовая ротация', 'rotations', 'Если окно урона заканчивается, примените сверхспособность раньше: усиление отряда всё равно сработает, хотя личные множители будут ниже.', '6', '{"visual":{"kind":"rotation","items":[{"id":"step-1","name":"Доведите сигнал до среднего","description":"На низком сигнале примените перенаправление и затем «Прерывистое существование». Вход через «Я здесь» также поднимает низкий сигнал до среднего.","imageUrl":"","stats":[]},{"id":"step-2","name":"Закончите цепочку атак","description":"На среднем сигнале проведите три удара «Перекрёстных помех». Последний удар открывает «Прощание с тобой».","imageUrl":"","stats":[]},{"id":"step-3","name":"Поднимите сигнал до высокого","description":"Примените «Прощание с тобой». Оно расходует «Оптическую иллюзию» и повышает средний сигнал до высокого.","imageUrl":"","stats":[]},{"id":"step-4","name":"Дайте усиления и смените героя","description":"Примените «У тебя бывает дежавю?» на высоком сигнале и передайте поле основному ДД. Усиления отряда и «Воспоминание» работают во время его выхода.","imageUrl":"","stats":[]}]}}' FROM nte_guide_0056;

INSERT INTO guide_sections(id,guide_id,title,section_type,content_markdown,position,meta_json) SELECT 'guide-elyms-0056-tips', 'guide-elyms-0056', 'Советы и ошибки', 'tips', 'Не задерживайте смену героя после сверхспособности: «Воспоминание» срабатывает вне поля. Уровень сигнала сбрасывается после сверхспособности или выхода из боя. Против одиночной цели и группы форма сверхспособности выбирается при сканировании ближайших целей.', '7', '{}' FROM nte_guide_0056;

INSERT OR IGNORE INTO teams(id,slug,guide_id,title,team_type,budget,difficulty,good_at,weak_at,synergy,rotation,rotation_steps_json,status) SELECT 'elyms-hathor', 'elyms-hathor', 'guide-elyms-0056', 'Космос: Элимс и Хатор', 'Урон космоса', 'Mixed', 'Средняя', 'Окна урона космоса', 'Зависит от готовности сверхспособности Элимс', 'Элимс усиливает атаку отряда; лечение помогает провести ротацию без срыва.', 'Подготовьте поле: используйте лечение или щит при необходимости.
На низком сигнале примените перенаправление и затем «Прерывистое существование». Вход через «Я здесь» также поднимает низкий сигнал до среднего.
На среднем сигнале проведите три удара «Перекрёстных помех». Последний удар открывает «Прощание с тобой». Примените «Прощание с тобой». Оно расходует «Оптическую иллюзию» и повышает средний сигнал до высокого.
Дайте сверхспособность Элимс и переключитесь на Хатор.', '["Подготовьте поле: используйте лечение или щит при необходимости.","На низком сигнале примените перенаправление и затем «Прерывистое существование». Вход через «Я здесь» также поднимает низкий сигнал до среднего.","На среднем сигнале проведите три удара «Перекрёстных помех». Последний удар открывает «Прощание с тобой». Примените «Прощание с тобой». Оно расходует «Оптическую иллюзию» и повышает средний сигнал до высокого.","Дайте сверхспособность Элимс и переключитесь на Хатор."]', 'published' FROM nte_guide_0056;

