INSERT OR IGNORE INTO teams(id,slug,guide_id,title,team_type,budget,difficulty,good_at,weak_at,synergy,rotation,rotation_steps_json,status) SELECT 'elyms-hotori', 'elyms-hotori', 'guide-elyms-0056', 'Космос: окно Хотори', 'Урон космоса', 'Mixed', 'Средняя', 'Окна урона космоса', 'Зависит от готовности сверхспособности Элимс', 'Элимс усиливает атаку отряда; лечение помогает провести ротацию без срыва.', 'Подготовьте поле: используйте лечение или щит при необходимости.
На низком сигнале примените перенаправление и затем «Прерывистое существование». Вход через «Я здесь» также поднимает низкий сигнал до среднего.
На среднем сигнале проведите три удара «Перекрёстных помех». Последний удар открывает «Прощание с тобой». Примените «Прощание с тобой». Оно расходует «Оптическую иллюзию» и повышает средний сигнал до высокого.
Дайте сверхспособность Элимс и переключитесь на Хотори для её окна взрывного урона.', '["Подготовьте поле: используйте лечение или щит при необходимости.","На низком сигнале примените перенаправление и затем «Прерывистое существование». Вход через «Я здесь» также поднимает низкий сигнал до среднего.","На среднем сигнале проведите три удара «Перекрёстных помех». Последний удар открывает «Прощание с тобой». Примените «Прощание с тобой». Оно расходует «Оптическую иллюзию» и повышает средний сигнал до высокого.","Дайте сверхспособность Элимс и переключитесь на Хотори для её окна взрывного урона."]', 'published' FROM nte_guide_0056;

