INSERT OR IGNORE INTO news(id,slug,title,summary,body_markdown,category,source_name,source_url,image_url,tags_json,status,created_at) VALUES ('patch-1-5-20261111', 'patch-1-5-elyms', 'NTE 1.5: Элимс, новая дуга и облики', 'В версии 1.5 вышли Элимс и «Эхо в режиме ожидания», вернулась Шинку и открылась новая сюжетная глава.', 'Элимс присоединилась к ростеру 11 ноября. Её доска и исследование дуги доступны до 2 декабря, 05:59 (UTC+8).

**Облики.** У Элимс появились «Мистика Y2K» в магазине, «Парящие лепестки» на доске и «Ветроцвет» за 10-й уровень связи. На доске возвращения Шинку доступна «Ученица Терраси».

**Сюжет и события.** Открылись эпизод «Встретимся в потоке данных», паломничество «Янтарная королева» и «Городская логистика». Условия и сроки указаны в заметках обновления.', 'Обновления', 'Neverness to Everness', 'https://nte.perfectworld.com/ru/article/news/gamenews/20261109/264953.html', '/nte-meta/game-assets/5c7f06ecc2d2f411dd7d.webp', '["1.5","Элимс","Шинку"]', 'published', '2026-11-11 03:00:00');

